/**
 * The settings with a Debug section added. Only provided when RuneLite runs in developer mode, so a normal client
 * never shows or uses the endpoint override.
 */
@ConfigGroup(PvKneeConfig.GROUP)
public interface PvKneeDevConfig extends PvKneeConfig
{
	@ConfigSection(
		name = "Debug",
		description = "Settings for testing the plugin; only shown in developer mode",
		position = 99,
		closedByDefault = true
	)
	String debugSection = "debug";

	@ConfigItem(
		keyName = "endpointOverride",
		name = "Endpoint override",
		description = "Replaces the clan endpoint URL, for testing against another sheet or previewing a draft bingo",
		section = debugSection
	)
	default String endpointOverride()
	{
		return "";
	}
}

package com.pvknee;

import com.pvknee.blocks.BingoView;
import com.pvknee.blocks.BlockContext;
import com.pvknee.blocks.BlockRegistry;
import com.pvknee.blocks.Icons;
import com.pvknee.blocks.PageNavigator;
import com.pvknee.blocks.Times;
import com.pvknee.data.Block;
import com.pvknee.data.ClanData;
import com.pvknee.data.ClanDataClient;
import com.pvknee.data.Page;
import com.pvknee.player.PlayerInfo;
import com.pvknee.player.PlayerState;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Notice;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import com.pvknee.ui.TopBar;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class PvKneePanel extends PluginPanel implements PageNavigator
{
	private static final int SUPPORTED_VERSION = 1;
	private static final Duration COUNTDOWN_INTERVAL = Duration.ofMinutes(1);
	private static final Duration REFRESH_INTERVAL = Duration.ofMinutes(10);

	private final ClanDataClient client;
	private final BlockRegistry blocks;
	private final Icons icons;
	private final DevLog devLog;
	private final BingoView bingoView;
	private final PlayerInfo playerInfo;
	private final TopBar topBar = new TopBar(this::showPage, () -> refresh(false, true, "button"));
	private final Notice notice = new Notice();
	private final Notice.Line errorLine = notice.addLine();
	private final Notice.Line lastUpdatedLine = notice.addLine();
	private final Notice.Line versionLine = notice.addLine();
	private final JPanel content = new JPanel();
	private final JScrollPane scrollPane;
	private final Timer countdownTimer = new Timer((int) COUNTDOWN_INTERVAL.toMillis(), e -> updateLive());
	private final Timer refreshTimer = new Timer((int) REFRESH_INTERVAL.toMillis(), e -> refresh(true, false, "timer"));

	private ClanData data;
	/** When the data was last loaded from the endpoint; null while only the saved copy is shown. */
	private Instant loadedAt;
	/** When the data on screen was fetched, from the endpoint or the saved copy. */
	private Instant updatedAt;
	private boolean loading;
	/** The page on screen, so a redraw of the same page keeps its scroll position. */
	private String shownPageId;
	/** Countdowns and bars on the current page, updated in place every minute. */
	private List<Runnable> liveUpdates = new ArrayList<>();

	@Inject
	PvKneePanel(ClanDataClient client, BlockRegistry blocks, Icons icons, DevLog devLog, PlayerInfo playerInfo)
	{
		super(false);
		this.client = client;
		this.blocks = blocks;
		this.icons = icons;
		this.devLog = devLog;
		this.bingoView = new BingoView(devLog);
		this.playerInfo = playerInfo;

		setLayout(new BorderLayout(0, 10));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel(new BorderLayout(0, 10));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(topBar, BorderLayout.NORTH);
		top.add(notice, BorderLayout.CENTER);

		content.setLayout(new DynamicGridLayout(0, 1, 0, Spacing.BLOCK_GAP));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel contentWrapper = new WidthTrackingPanel();
		contentWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contentWrapper.add(content, BorderLayout.NORTH);

		scrollPane = new JScrollPane(contentWrapper);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setBorder(null);

		add(top, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
	}

	@Override
	public void onActivate()
	{
		if (data == null)
		{
			client.loadSaved((saved, savedAt) -> SwingUtilities.invokeLater(() -> showSaved(saved, savedAt)));
			refresh(false, false, "first open");
		}
		else if (loadedAt == null || Instant.now().isAfter(loadedAt.plus(REFRESH_INTERVAL)))
		{
			refresh(true, false, "open, data is old");
		}
		else
		{
			updateLive();
		}

		countdownTimer.restart();
		refreshTimer.restart();
	}

	@Override
	public void onDeactivate()
	{
		stopUpdates();
	}

	/**
	 * Stops the countdown and refresh timers until the panel is shown again.
	 */
	void stopUpdates()
	{
		countdownTimer.stop();
		refreshTimer.stop();
	}

	/**
	 * Reloads the clan data, unless it loaded less than a minute ago or, for automatic tries, a failure means waiting
	 * longer. A quiet refresh keeps the page as it is while loading, and on failure only shows when the data on
	 * screen is from.
	 */
	private void refresh(boolean quiet, boolean manual, String reason)
	{
		if (loading)
		{
			devLog.log("refresh: {} skipped, already loading", reason);
			return;
		}
		if (!client.mayLoad(manual))
		{
			devLog.log("refresh: {} skipped, loaded recently or waiting after a failure", reason);
			Instant elsewhere = client.loadedAt();
			if (elsewhere != null && (loadedAt == null || elsewhere.isAfter(loadedAt)) && client.latest() != null)
			{
				// Loaded for a chat feature while the panel was closed.
				show(client.latest(), elsewhere);
			}
			return;
		}

		devLog.log("refresh: {}{}", reason, quiet ? " (quiet)" : "");
		loading = true;
		if (!quiet)
		{
			topBar.setLoading(true);
		}

		client.fetch(
			data -> SwingUtilities.invokeLater(() -> show(data, client.loadedAt())),
			e ->
			{
				devLog.log("load: failed, {}", e.getMessage(), e);
				SwingUtilities.invokeLater(() ->
				{
					loading = false;
					topBar.setLoading(false);
					if (!quiet)
					{
						errorLine.setMessage("Couldn't load the clan panel. Press the refresh button to try again.", ColorScheme.PROGRESS_ERROR_COLOR);
					}
					showLastUpdated();
				});
			});
	}

	private void show(ClanData data, Instant at)
	{
		// Cleared first, so a response that fails to display cannot stop all later refreshes.
		loading = false;
		topBar.setLoading(false);
		devLog.log("load: {} pages", data.getPages().size());
		loadedAt = at;
		updatedAt = loadedAt;
		errorLine.clear();
		lastUpdatedLine.clear();
		display(data);
	}

	/**
	 * Shows the saved copy, unless there is none or fresh data has already arrived. While a load is still running, the "Last updated"
	 * line waits until it fails, so the page doesn't jump when the fresh data replaces the saved copy.
	 */
	private void showSaved(ClanData data, Instant savedAt)
	{
		if (data == null || this.data != null)
		{
			return;
		}

		devLog.log("load: showing saved copy from {}", savedAt);
		updatedAt = savedAt;
		display(data);
		if (!loading)
		{
			showLastUpdated();
		}
	}

	private void showLastUpdated()
	{
		if (data == null)
		{
			return;
		}

		lastUpdatedLine.setMessage("Last updated " + Times.time(updatedAt), ThemeColours.from(data.getTheme()).getMuted());
	}

	private void display(ClanData data)
	{
		this.data = data;
		if (data.getVersion() > SUPPORTED_VERSION)
		{
			versionLine.setMessage("A newer plugin version is available", ThemeColours.from(data.getTheme()).getMuted());
		}
		else
		{
			versionLine.clear();
		}

		Page previous = topBar.getSelected();
		String previousId = previous == null ? null : previous.getId();
		PlayerState player = playerInfo.get();
		bingoView.update(data.getBingo(), player);
		data.getPages().stream()
			.filter(page -> page.isShow() && !player.hasRank(page.getRank()))
			.forEach(page -> devLog.log("pages: {} hidden, needs rank {}", page.getId(), page.getRank()));
		List<Page> pages = data.getPages().stream()
			.filter(this::isVisible)
			.collect(Collectors.toList());
		Page selected = pages.stream()
			.filter(page -> Objects.equals(page.getId(), previousId))
			.findFirst()
			.orElse(pages.isEmpty() ? null : pages.get(0));
		topBar.setPages(pages, selected, ThemeColours.from(data.getTheme()));

		if (selected == null)
		{
			showMessage("No pages to show");
		}
		else
		{
			showPage(selected);
		}
	}

	/**
	 * Builds the current page again in place, e.g. after a setting that changes how it looks.
	 */
	void redraw()
	{
		if (data != null)
		{
			showPage(topBar.getSelected());
			if (lastUpdatedLine.isVisible())
			{
				showLastUpdated();
			}
		}
	}

	/**
	 * Updates the pages after a change in game: rank-gated pages appear or disappear, and the current page is built
	 * again (staying on it while it is still shown).
	 */
	void playerChanged()
	{
		if (data != null)
		{
			display(data);
		}
	}

	/**
	 * Updates the countdowns and bars on the current page without rebuilding it.
	 */
	private void updateLive()
	{
		liveUpdates.forEach(Runnable::run);
	}

	/**
	 * Builds the page. A different page opens at the top; the same page keeps its scroll position.
	 */
	private void showPage(Page page)
	{
		if (page == null)
		{
			return;
		}

		ThemeColours colours = ThemeColours.from(data.getTheme());
		topBar.setShown(page);

		liveUpdates = new ArrayList<>();
		bingoView.clearListeners();
		BlockContext context = new BlockContext(data, colours, icons, this, playerInfo.get(), devLog, bingoView, liveUpdates);

		content.removeAll();
		for (Block block : page.getBlocks())
		{
			JComponent component = blocks.render(block, context);
			if (component != null)
			{
				content.add(component);
			}
		}
		content.revalidate();
		content.repaint();

		if (!Objects.equals(page.getId(), shownPageId))
		{
			shownPageId = page.getId();
			scrollPane.getVerticalScrollBar().setValue(0);
		}
	}

	@Override
	public boolean canOpen(String pageId)
	{
		return findPage(pageId) != null;
	}

	@Override
	public void open(String pageId)
	{
		Page page = findPage(pageId);
		if (page != null)
		{
			topBar.select(page);
		}
	}

	private Page findPage(String pageId)
	{
		if (data == null || pageId == null)
		{
			return null;
		}
		return data.getPages().stream()
			.filter(page -> pageId.equals(page.getId()) && isVisible(page))
			.findFirst()
			.orElse(null);
	}

	/**
	 * Shown pages, except those whose rank is above the member's clan rank.
	 */
	private boolean isVisible(Page page)
	{
		return page.isShow() && playerInfo.get().hasRank(page.getRank());
	}

	private void showMessage(String message)
	{
		liveUpdates = new ArrayList<>();
		bingoView.clearListeners();
		shownPageId = null;
		topBar.setShown(null);
		content.removeAll();
		content.add(Labels.label(message, Color.WHITE, FontManager.getRunescapeFont(), Labels.CONTENT_WIDTH, false));
		content.revalidate();
		content.repaint();
	}

	/**
	 * Scroll pane content that always matches the visible width, so nothing is cut off on the right.
	 */
	private static class WidthTrackingPanel extends JPanel implements Scrollable
	{
		WidthTrackingPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.pvknee;

import com.google.inject.Injector;
import com.google.inject.Provides;
import com.pvknee.bingo.TeamChatIcons;
import com.pvknee.bingo.TeamDots;
import com.pvknee.bingo.TeamHeadOverlay;
import com.pvknee.bingo.TeamOverlay;
import com.pvknee.bingo.TeamRoster;
import com.pvknee.blocks.Icons;
import com.pvknee.blocks.Times;
import com.pvknee.chat.ChatCommands;
import com.pvknee.chat.LoginMessage;
import com.pvknee.data.ClanDataClient;
import com.pvknee.data.SavedCopy;
import com.pvknee.player.PlayerInfo;
import com.pvknee.wom.LogoutUpdate;
import java.awt.image.BufferedImage;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.extern.slf4j.Slf4j;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "PvKnee Clan",
	internalName = "pvknee",
	description = "Skill and Boss of the Week, events, links and bingo for the PvKnee clan",
	tags = {"clan", "sotw", "botw", "events", "wom"}
)
public class PvKneePlugin extends Plugin
{
	@Inject
	private Injector injector;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SavedCopy savedCopy;

	@Inject
	private PvKneeConfig config;

	@Inject
	private PlayerInfo playerInfo;

	@Inject
	private ChatCommands chatCommands;

	@Inject
	private LoginMessage loginMessage;

	@Inject
	private LogoutUpdate logoutUpdate;

	@Inject
	private TeamRoster teamRoster;

	@Inject
	private TeamChatIcons teamChatIcons;

	@Inject
	private TeamHeadOverlay teamHeadOverlay;

	@Inject
	private TeamOverlay teamOverlay;

	@Inject
	private ClanDataClient clanData;

	@Inject
	private Icons icons;

	@Inject
	private TeamDots teamDots;

	@Inject
	private ClientThread clientThread;

	private PvKneePanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		try
		{
			savedCopy.setDirectory(getPluginDirectory());
		}
		catch (IOException e)
		{
			log.debug("No plugin folder, so the clan data will not be saved", e);
		}

		Times.setUtc(config.showTimesInUtc());
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		panel = injector.getInstance(PvKneePanel.class);

		navButton = NavigationButton.builder()
			.tooltip("PvKnee")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		playerInfo.start(panel::playerChanged);
		chatCommands.start();
		loginMessage.start();
		logoutUpdate.start();
		teamRoster.start();
		teamChatIcons.start();
		teamHeadOverlay.start();
		teamOverlay.start();
		log.debug("PvKnee started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		playerInfo.stop();
		chatCommands.stop();
		loginMessage.stop();
		logoutUpdate.stop();
		teamOverlay.stop();
		teamHeadOverlay.stop();
		teamChatIcons.stop();
		teamRoster.stop();
		clientToolbar.removeNavigation(navButton);
		panel.stopUpdates();
		navButton = null;
		panel = null;

		// Nothing is kept in memory while the plugin is off.
		clanData.clear();
		SwingUtilities.invokeLater(icons::clear);
		clientThread.invoke(teamDots::clear);
		log.debug("PvKnee stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PvKneeConfig.GROUP.equals(event.getGroup()) && "showTimesInUtc".equals(event.getKey()))
		{
			Times.setUtc(config.showTimesInUtc());
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.redraw();
				}
			});
		}
	}

	/**
	 * The settings; in developer mode with the Debug section as well.
	 */
	@Provides
	PvKneeConfig provideConfig(ConfigManager configManager, @Named("developerMode") boolean developerMode)
	{
		return developerMode ? configManager.getConfig(PvKneeDevConfig.class) : configManager.getConfig(PvKneeConfig.class);
	}
}

