import net.runelite.client.plugins.playerindicators.PlayerIndicatorsPlugin;
import net.runelite.client.plugins.playerindicators.PlayerNameLocation;
import net.runelite.client.util.Text;

/**
 * Where RuneLite's Player Indicators plugin draws a player's name, so the team dot can sit just left of it. Follows
 * that plugin's rules: it must be on with a name position set, and the player's group (you, party, friends, friends
 * chat, team, clan or others) turned on. Used on the client thread.
 */
@Singleton
class IndicatorNames
{
	/** Player Indicators' gaps above the head and right of the model. */
	private static final int OVERHEAD_MARGIN = 40;
	private static final int RIGHT_MARGIN = 10;

	private final Client client;
	private final PluginManager pluginManager;
	private final ChatIconManager chatIconManager;
	private final PartyService partyService;
	private final PlayerIndicatorsConfig config;

	@Inject
	IndicatorNames(Client client, PluginManager pluginManager, ConfigManager configManager, ChatIconManager chatIconManager,
		PartyService partyService)
	{
		this.client = client;
		this.pluginManager = pluginManager;
		this.chatIconManager = chatIconManager;
		this.partyService = partyService;
		this.config = configManager.getConfig(PlayerIndicatorsConfig.class);
	}

	/**
	 * Why Player Indicators draws no names at all, or null when it may draw some.
	 */
	String off()
	{
		Plugin plugin = pluginManager.getPlugins().stream()
			.filter(p -> p instanceof PlayerIndicatorsPlugin)
			.findFirst()
			.orElse(null);
		if (plugin == null || !pluginManager.isPluginActive(plugin))
		{
			return "Player Indicators is off";
		}
		return config.playerNamePosition() == PlayerNameLocation.DISABLED ? "Player Indicators names are off" : null;
	}

	/**
	 * Whether Player Indicators draws this player's name.
	 */
	boolean named(Player player)
	{
		if (player.getName() == null)
		{
			return false;
		}
		if (player == client.getLocalPlayer())
		{
			return on(config.highlightOwnPlayer());
		}
		if (partyService.isInParty() && on(config.highlightPartyMembers()) && partyService.getMemberByDisplayName(player.getName()) != null)
		{
			return true;
		}
		if (player.isFriend() && on(config.highlightFriends()))
		{
			return true;
		}
		if (player.isFriendsChatMember() && on(config.highlightFriendsChat()))
		{
			return true;
		}
		Player local = client.getLocalPlayer();
		if (player.getTeam() > 0 && local != null && local.getTeam() == player.getTeam() && on(config.highlightTeamMembers()))
		{
			return true;
		}
		if (player.isClanMember() && on(config.highlightClanMembers()))
		{
			return true;
		}
		return !player.isFriendsChatMember() && !player.isClanMember() && on(config.highlightOthers());
	}

	/**
	 * The width of the rank icon Player Indicators draws in front of the name; 0 for none.
	 */
	int rankWidth(Player player)
	{
		BufferedImage rank = null;
		if (player.isFriendsChatMember() && config.showFriendsChatRanks())
		{
			FriendsChatRank fcRank = friendsChatRank(player);
			rank = fcRank == FriendsChatRank.UNRANKED ? null : chatIconManager.getRankImage(fcRank);
		}
		else if (player.isClanMember() && config.showClanChatRanks())
		{
			ClanTitle title = clanTitle(player);
			rank = title == null ? null : chatIconManager.getRankImage(title);
		}
		return rank == null ? 0 : rank.getWidth();
	}

	/**
	 * The point just left of the name and its rank icon, at the middle of the text; null when off screen.
	 */
	Point leftOfName(Graphics2D graphics, Player player, int rankWidth)
	{
		PlayerNameLocation position = config.playerNamePosition();
		boolean right = position == PlayerNameLocation.MODEL_RIGHT;
		int zOffset = position == PlayerNameLocation.ABOVE_HEAD ? player.getLogicalHeight() + OVERHEAD_MARGIN : player.getLogicalHeight() / 2;
		Point text = player.getCanvasTextLocation(graphics, right ? "" : Text.sanitize(player.getName()), zOffset);
		if (text == null)
		{
			return null;
		}

		int x = text.getX() + (right ? RIGHT_MARGIN : 0);
		if (rankWidth > 0)
		{
			// Where Player Indicators puts the rank icon's left edge.
			x -= (right ? 0 : rankWidth / 2) + 1;
		}
		FontMetrics metrics = graphics.getFontMetrics();
		return new Point(x, text.getY() - (metrics.getHeight() - metrics.getMaxDescent()) / 2);
	}

	private boolean on(PlayerIndicatorsConfig.HighlightSetting setting)
	{
		return setting == PlayerIndicatorsConfig.HighlightSetting.ENABLED
			|| setting == PlayerIndicatorsConfig.HighlightSetting.PVP
			&& (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1 || client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1);
	}

	private FriendsChatRank friendsChatRank(Player player)
	{
		FriendsChatManager manager = client.getFriendsChatManager();
		FriendsChatMember member = manager == null ? null : manager.findByName(Text.removeTags(player.getName()));
		return member == null ? FriendsChatRank.UNRANKED : member.getRank();
	}

	private ClanTitle clanTitle(Player player)
	{
		ClanChannel channel = client.getClanChannel();
		ClanSettings settings = client.getClanSettings();
		ClanChannelMember member = channel == null || settings == null ? null : channel.findMember(player.getName());
		return member == null ? null : settings.titleForRank(member.getRank());
	}
}

package com.pvknee.bingo;

import com.pvknee.DevLog;
import com.pvknee.PvKneeConfig;
import java.util.EnumSet;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Team dots in front of the names of clan members on a bingo team in public and clan chat, while a bingo runs. Added
 * the way RuneLite adds its own chat icons: as each chat line is built, the dot's image tag goes in front of the
 * sender's name on the script's stack. The clan rank icon stays, the game's widgets are untouched and messages the
 * member sends are unchanged, so turning it off only needs a chat refresh. Hidden where overhead dots are: in the
 * Wilderness, on PvP worlds and in PvP areas. Used on the client thread.
 */
@Singleton
public class TeamChatIcons
{
	private static final Set<ChatMessageType> TYPES = EnumSet.of(ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT,
		ChatMessageType.CLAN_CHAT);
	private static final String CHAT_MESSAGE_BUILDING = "chatMessageBuilding";
	/** Where the sender's name sits on the object stack while a chat line is built, counted from the top. */
	private static final int NAME_FROM_TOP = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final TeamRoster roster;
	private final TeamDots dots;
	private final PvKneeConfig config;
	private final DevLog devLog;

	/** Why the dots are hidden for PvP, as of the last tick, so the chat is rebuilt when it changes. */
	private String pvpHidden;

	@Inject
	TeamChatIcons(Client client, ClientThread clientThread, EventBus eventBus, TeamRoster roster, TeamDots dots,
		PvKneeConfig config, DevLog devLog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.roster = roster;
		this.dots = dots;
		this.config = config;
		this.devLog = devLog;
	}

	/**
	 * Starts the dots. Call after the roster has started.
	 */
	public void start()
	{
		eventBus.register(this);
		roster.onChange(this::redraw);
	}

	public void stop()
	{
		eventBus.unregister(this);
		clientThread.invoke(() ->
		{
			pvpHidden = null;
			client.refreshChat();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PvKneeConfig.GROUP.equals(event.getGroup()) && "teamIconsInChat".equals(event.getKey()))
		{
			devLog.log("chat icons: turned {}", config.teamIconsInChat() ? "on" : "off");
			clientThread.invoke(this::redraw);
		}
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		// The clan's member list arrives after login, so lines built before it get their dots now.
		client.refreshChat();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		String hidden = TeamDots.hiddenForPvp(client);
		if (!Objects.equals(hidden, pvpHidden))
		{
			pvpHidden = hidden;
			devLog.log("chat icons: {}", hidden == null ? "shown again" : "hidden, " + hidden);
			client.refreshChat();
		}
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!CHAT_MESSAGE_BUILDING.equals(event.getEventName()) || !config.teamIconsInChat() || roster.isEmpty()
			|| pvpHidden != null)
		{
			return;
		}

		int uid = client.getIntStack()[client.getIntStackSize() - 1];
		MessageNode node = client.getMessages().get(uid);
		if (node == null || !TYPES.contains(node.getType()))
		{
			return;
		}

		TeamRoster.Team team = roster.clanTeamOf(node.getName());
		String tag = team == null ? "" : dots.chatTag(team.getColour());
		if (!tag.isEmpty())
		{
			// Strings share the object stack.
			Object[] stack = client.getObjectStack();
			int name = client.getObjectStackSize() - NAME_FROM_TOP;
			stack[name] = tag + stack[name];
		}
	}

	private void redraw()
	{
		// Registered now, so the client has loaded them by the time the chat is built.
		roster.teams().forEach(team -> dots.chatTag(team.getColour()));
		client.refreshChat();
	}
}

package com.pvknee.bingo;

import com.pvknee.data.Bingo;
import java.awt.Color;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import net.runelite.client.util.ColorUtil;

/**
 * A bingo team's colour: its sheet colour, else one from a fixed palette. Used wherever a team's colour shows.
 */
public final class TeamColours
{
	/** Red, blue, green, yellow, purple and orange, then repeating. */
	private static final Color[] PALETTE = {
		new Color(0xEF5350), new Color(0x42A5F5), new Color(0x66BB6A),
		new Color(0xFFEE58), new Color(0xAB47BC), new Color(0xFFA726),
	};

	private TeamColours()
	{
	}

	/**
	 * The team's colour among these teams. Without a sheet colour, the palette goes by team name, since the endpoint
	 * sorts teams by points and a team's default colour must not change as the points do.
	 */
	public static Color of(List<Bingo.Team> teams, Bingo.Team team)
	{
		Color colour = team.getColour() == null ? null : ColorUtil.fromHex(team.getColour().trim());
		if (colour != null)
		{
			return colour;
		}

		List<String> names = teams.stream()
			.map(t -> Objects.toString(t.getName(), ""))
			.sorted(Comparator.naturalOrder())
			.collect(Collectors.toList());
		int index = Math.max(0, names.indexOf(Objects.toString(team.getName(), "")));
		return PALETTE[index % PALETTE.length];
	}
}

package com.pvknee.bingo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ChatIconManager;

/**
 * The team dots: small filled circles in a team's colour with a thin dark outline, the size of a chat rank icon.
 * Each colour is drawn and registered as a chat icon once, and kept while the client runs, since chat icons cannot
 * be removed. Used on the client thread.
 */
@Singleton
public class TeamDots
{
	public static final int SIZE = 11;
	private static final Color OUTLINE = new Color(0, 0, 0, 200);

	private final ChatIconManager chatIconManager;
	private final Map<Integer, BufferedImage> images = new HashMap<>();
	/** Chat icon ids by colour. */
	private final Map<Integer, Integer> chatIcons = new HashMap<>();

	@Inject
	TeamDots(ChatIconManager chatIconManager)
	{
		this.chatIconManager = chatIconManager;
	}

	/**
	 * Why no team dots may show here, or null where they may: dots are never shown where they could mark PvP
	 * opponents. Call on the client thread.
	 */
	public static String hiddenForPvp(Client client)
	{
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1 ? "in the Wilderness"
			: WorldType.isPvpWorld(client.getWorldType()) ? "on a PvP world"
			: client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1 ? "in a PvP area"
			: null;
	}

	/**
	 * Forgets the drawn dots. The chat icons stay registered, since the client cannot remove them; they are reused
	 * if the plugin is turned on again.
	 */
	public void clear()
	{
		images.clear();
	}

	public BufferedImage image(Color colour)
	{
		return images.computeIfAbsent(colour.getRGB(), rgb -> draw(colour));
	}

	/**
	 * The dot's chat image tag, e.g. "&lt;img=42&gt;"; empty until the client has loaded the icon.
	 */
	public String chatTag(Color colour)
	{
		return tag(chatIcons.computeIfAbsent(colour.getRGB(), rgb -> chatIconManager.registerChatIcon(image(colour))));
	}

	private String tag(int id)
	{
		int index = chatIconManager.chatIconIndex(id);
		return index < 0 ? "" : "<img=" + index + ">";
	}

	private static BufferedImage draw(Color colour)
	{
		BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Ellipse2D dot = new Ellipse2D.Double(0.5, 0.5, SIZE - 1, SIZE - 1);
		g.setColor(colour);
		g.fill(dot);
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(1f));
		g.draw(dot);
		g.dispose();
		return image;
	}
}

package com.pvknee.bingo;

import com.pvknee.DevLog;
import com.pvknee.PvKneeConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.events.PlayerSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * A team dot for each player on a bingo team, just left of the name RuneLite's Player Indicators plugin draws for
 * them; no name, no dot. The players on a team are kept as they spawn and despawn, so drawing never searches the
 * scene. Only clan members are marked. Hidden in the Wilderness, on PvP worlds and in PvP areas.
 */
@Singleton
public class TeamHeadOverlay extends Overlay
{
	private static final int NAME_GAP = 2;
	/** Lifts the dot a little above the middle of the name, where it looks centred. */
	private static final int LIFT = 2;

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final OverlayManager overlayManager;
	private final TeamRoster roster;
	private final TeamDots dots;
	private final IndicatorNames names;
	private final PvKneeConfig config;
	private final DevLog devLog;

	/** The players in the scene who are on a team. */
	private final Map<Player, TeamRoster.Team> shown = new HashMap<>();
	/** Those of them whose name Player Indicators draws, with the width of its rank icon; found each tick. */
	private final Map<Player, Integer> named = new HashMap<>();
	/**
	 * Why the dots are hidden, or null while they show. Worked out only when it can change: plugins or settings
	 * change, the bingo roster changes, the member logs in, or enters or leaves a PvP area.
	 */
	private String hiddenBecause = "starting";
	/** The last state logged, so it is logged once per change. */
	private String logged;

	@Inject
	TeamHeadOverlay(Client client, ClientThread clientThread, EventBus eventBus, OverlayManager overlayManager,
		TeamRoster roster, TeamDots dots, IndicatorNames names, PvKneeConfig config, DevLog devLog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.overlayManager = overlayManager;
		this.roster = roster;
		this.dots = dots;
		this.names = names;
		this.config = config;
		this.devLog = devLog;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/**
	 * Starts the dots. Call after the roster has started.
	 */
	public void start()
	{
		eventBus.register(this);
		roster.onChange(this::rosterChanged);
		overlayManager.add(this);
		clientThread.invoke(this::rosterChanged);
	}

	public void stop()
	{
		overlayManager.remove(this);
		eventBus.unregister(this);
		clientThread.invoke(() ->
		{
			shown.clear();
			named.clear();
			hiddenBecause = "starting";
			logged = null;
		});
	}

	@Subscribe
	public void onPlayerSpawned(PlayerSpawned event)
	{
		Player player = event.getPlayer();
		TeamRoster.Team team = roster.clanTeamOf(player.getName());
		if (team != null)
		{
			shown.put(player, team);
		}
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		shown.remove(event.getPlayer());
		named.remove(event.getPlayer());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			shown.clear();
			named.clear();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			// The world type decides whether this is a PvP world.
			updateHidden();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.INSIDE_WILDERNESS || event.getVarbitId() == VarbitID.PVP_AREA_CLIENT)
		{
			updateHidden();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Our own switch, or Player Indicators' name settings.
		clientThread.invoke(this::updateHidden);
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		clientThread.invoke(this::updateHidden);
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		// The clan's member list arrives after login, so players seen before it are checked again.
		findPlayers();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		named.clear();
		if (hiddenBecause == null)
		{
			// Only the team players in view, whose names Player Indicators may draw this tick.
			shown.keySet().stream()
				.filter(names::named)
				.forEach(player -> named.put(player, names.rankWidth(player)));
		}

		if (devLog.isEnabled())
		{
			String state = hiddenBecause != null ? "hidden, " + hiddenBecause
				: "drawn for " + named.size() + " of " + shown.size() + " team players in view" + (named.isEmpty() ? ""
					: " (" + named.keySet().stream().map(p -> Text.removeTags(p.getName())).sorted().collect(Collectors.joining(", ")) + ")");
			if (!state.equals(logged))
			{
				logged = state;
				devLog.log("overhead icons: {}", state);
			}
		}
	}

	/**
	 * Works out again why the dots are hidden, if they are. Call on the client thread.
	 */
	private void updateHidden()
	{
		String pvp = TeamDots.hiddenForPvp(client);
		hiddenBecause = !config.teamIconsAboveHeads() ? "turned off"
			: roster.isEmpty() ? "no bingo running"
			: pvp != null ? pvp
			: names.off();
	}

	private void rosterChanged()
	{
		findPlayers();
		updateHidden();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (hiddenBecause != null || named.isEmpty())
		{
			return null;
		}

		named.forEach((player, rankWidth) ->
		{
			TeamRoster.Team team = shown.get(player);
			Point name = team == null ? null : names.leftOfName(graphics, player, rankWidth);
			if (name != null)
			{
				graphics.drawImage(dots.image(team.getColour()),
					name.getX() - TeamDots.SIZE - NAME_GAP, name.getY() - TeamDots.SIZE / 2 - LIFT, null);
			}
		});
		return null;
	}

	/**
	 * Finds the players on a team among those in the scene, once each time the roster changes.
	 */
	private void findPlayers()
	{
		shown.clear();
		if (client.getGameState() != GameState.LOGGED_IN || roster.isEmpty())
		{
			return;
		}
		for (Player player : client.getTopLevelWorldView().players())
		{
			TeamRoster.Team team = player == null ? null : roster.clanTeamOf(player.getName());
			if (team != null)
			{
				shown.put(player, team);
			}
		}
	}
}

package com.pvknee.bingo;

import com.pvknee.DevLog;
import com.pvknee.PvKneeConfig;
import com.pvknee.blocks.Times;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * A small movable box with the member's team name in the team colour and the date and time in UTC to the minute, so
 * admins can tell when a screenshot was taken. Shown only while logged in, on a team, and the bingo runs.
 */
@Singleton
public class TeamOverlay extends OverlayPanel
{
	private static final String SEPARATOR = " · ";
	/** Longer team names are cut short with "...", so the box stays small. */
	private static final int MAX_NAME_WIDTH = 140;

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final OverlayManager overlayManager;
	private final TeamRoster roster;
	private final PvKneeConfig config;
	private final DevLog devLog;

	/** The member's team while the box shows, else null; checked each tick. */
	private TeamRoster.Team team;
	/** The team name as drawn, worked out once per team. */
	private TeamRoster.Team nameFor;
	private String name;
	/** The last state logged, so it is logged once per change. */
	private String logged;

	@Inject
	TeamOverlay(Client client, ClientThread clientThread, EventBus eventBus, OverlayManager overlayManager,
		TeamRoster roster, PvKneeConfig config, DevLog devLog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.overlayManager = overlayManager;
		this.roster = roster;
		this.config = config;
		this.devLog = devLog;
		setPosition(OverlayPosition.BOTTOM_LEFT);
	}

	/**
	 * Starts the box. Call after the roster has started.
	 */
	public void start()
	{
		eventBus.register(this);
		overlayManager.add(this);
	}

	public void stop()
	{
		overlayManager.remove(this);
		eventBus.unregister(this);
		clientThread.invoke(() ->
		{
			team = null;
			nameFor = null;
			logged = null;
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// No ticks while logged out, so hide it here.
			show(null, "logged out");
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		TeamRoster.Team own = player == null ? null : roster.teamOf(player.getName());
		show(own, !config.bingoTeamOverlay() ? "turned off"
			: roster.isEmpty() ? "no bingo running"
			: own == null ? "not on a team"
			: null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		TeamRoster.Team shown = team;
		if (shown == null)
		{
			return null;
		}

		FontMetrics metrics = graphics.getFontMetrics();
		if (nameFor != shown)
		{
			nameFor = shown;
			name = plainName(shown.getName(), metrics);
		}

		String stamp = Times.utcStamp(Instant.now());
		int width = metrics.stringWidth(name + SEPARATOR + stamp);
		panelComponent.setPreferredSize(new Dimension(width + 2 * ComponentConstants.STANDARD_BORDER, 0));
		panelComponent.getChildren().add(LineComponent.builder()
			// Overlay text reads opening colour tags only, so each part starts with its own.
			.left(ColorUtil.prependColorTag(name, shown.getColour()) + ColorUtil.prependColorTag(SEPARATOR + stamp, Color.WHITE))
			.build());
		return super.render(graphics);
	}

	/**
	 * The team name as plain text, so no tags in it take effect, cut short with "..." if it is too wide.
	 */
	private static String plainName(String teamName, FontMetrics metrics)
	{
		String plain = Text.removeTags(teamName == null ? "" : teamName).replace('<', '(').replace('>', ')').trim();
		if (metrics.stringWidth(plain) <= MAX_NAME_WIDTH)
		{
			return plain;
		}
		int length = plain.length();
		while (length > 0 && metrics.stringWidth(plain.substring(0, length).trim() + "...") > MAX_NAME_WIDTH)
		{
			length--;
		}
		return plain.substring(0, length).trim() + "...";
	}

	/**
	 * Shows the box for this team, or hides it for the reason given.
	 */
	private void show(TeamRoster.Team own, String hiddenBecause)
	{
		team = hiddenBecause == null ? own : null;
		String state = hiddenBecause == null ? "shown for " + own.getName() : "hidden, " + hiddenBecause;
		if (!state.equals(logged))
		{
			logged = state;
			devLog.log("team overlay: {}", state);
		}
	}
}

package com.pvknee.bingo;

import com.pvknee.DevLog;
import com.pvknee.blocks.Times;
import com.pvknee.data.Bingo;
import com.pvknee.data.ClanData;
import com.pvknee.data.ClanDataClient;
import com.pvknee.player.PlayerState;
import java.awt.Color;
import java.time.Instant;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Who is on which bingo team, while a bingo runs: empty before the start, after the end and with no bingo. Built on
 * the client thread whenever new data loads; each tick only checks whether the bingo has just ended.
 */
@Singleton
public class TeamRoster
{
	@Value
	public static class Team
	{
		String name;
		Color colour;
	}

	private final ClanDataClient clanData;
	private final Client client;
	private final ClientThread clientThread;
	private final Runnable onData = this::dataLoaded;
	private final EventBus eventBus;
	private final DevLog devLog;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	/** Each player's team, by {@link PlayerState#nameKey}. */
	private volatile Map<String, Team> teams = Collections.emptyMap();
	/** The data the roster was built from, so it is built again only when new data arrives. */
	private ClanData builtFrom;
	private Instant endsAt;
	/** The last roster logged, so a reload that changes nothing logs nothing. */
	private String logged;
	/** The clan's members by {@link PlayerState#nameKey}, and the clan settings they were read from. */
	private Set<String> clanMembers = Collections.emptySet();
	private ClanSettings clanMembersFrom;

	@Inject
	TeamRoster(ClanDataClient clanData, Client client, ClientThread clientThread, EventBus eventBus, DevLog devLog)
	{
		this.clanData = clanData;
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.devLog = devLog;
	}

	public void start()
	{
		eventBus.register(this);
		clanData.onData(onData);
		dataLoaded();
	}

	public void stop()
	{
		clanData.removeOnData(onData);
		eventBus.unregister(this);
		listeners.clear();
		teams = Collections.emptyMap();
		builtFrom = null;
		endsAt = null;
		logged = null;
		clanMembers = Collections.emptySet();
		clanMembersFrom = null;
	}

	/**
	 * Runs after the roster changes, until {@link #stop}.
	 */
	public void onChange(Runnable listener)
	{
		listeners.add(listener);
	}

	/**
	 * The team of the player with this name, which may carry chat tags; null when not on a team or no bingo runs.
	 */
	public Team teamOf(String name)
	{
		return name == null || teams.isEmpty() ? null : teams.get(PlayerState.nameKey(Text.removeTags(name)));
	}

	/**
	 * The team of this player if they are also in the clan's member list, so a bingo sheet cannot be used to mark
	 * players outside the clan; null otherwise. Call on the client thread.
	 */
	public Team clanTeamOf(String name)
	{
		Team team = teamOf(name);
		return team != null && isClanMember(name) ? team : null;
	}

	private boolean isClanMember(String name)
	{
		ClanSettings settings = client.getClanSettings();
		if (settings == null)
		{
			return false;
		}
		if (settings != clanMembersFrom)
		{
			clanMembersFrom = settings;
			clanMembers = settings.getMembers().stream()
				.map(ClanMember::getName)
				.filter(Objects::nonNull)
				.map(PlayerState::nameKey)
				.collect(Collectors.toSet());
		}
		return clanMembers.contains(PlayerState.nameKey(Text.removeTags(name)));
	}

	/**
	 * Every team with at least one player.
	 */
	public Collection<Team> teams()
	{
		return new HashSet<>(teams.values());
	}

	public boolean isEmpty()
	{
		return teams.isEmpty();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (endsAt != null && !Instant.now().isBefore(endsAt))
		{
			log("none, the bingo has ended");
			set(Collections.emptyMap(), null);
		}
	}

	/**
	 * Builds the roster again from the newest data, on the client thread.
	 */
	private void dataLoaded()
	{
		clientThread.invoke(() ->
		{
			ClanData data = clanData.latest();
			if (data != builtFrom)
			{
				builtFrom = data;
				build(data == null ? null : data.getBingo());
			}
		});
	}

	private void build(Bingo bingo)
	{
		Instant end = bingo == null ? null : Times.parse(bingo.getEndsAt());
		if (bingo == null || bingo.getState() != Bingo.State.RUNNING || end != null && !Instant.now().isBefore(end))
		{
			log(bingo == null ? "none, no bingo"
				: bingo.getState() != Bingo.State.RUNNING ? "none, bingo " + bingo.getState() : "none, the bingo has ended");
			set(Collections.emptyMap(), null);
			return;
		}

		Map<String, Team> next = new HashMap<>();
		for (Bingo.Team team : bingo.getTeams())
		{
			Team entry = new Team(team.getName(), TeamColours.of(bingo.getTeams(), team));
			for (Bingo.Member member : team.getMembers())
			{
				if (member.getName() != null)
				{
					next.putIfAbsent(PlayerState.nameKey(member.getName()), entry);
				}
			}
		}
		log(bingo.getTeams().size() + " teams, " + next.size() + " players, until " + bingo.getEndsAt());
		set(Collections.unmodifiableMap(next), end);
	}

	private void log(String roster)
	{
		if (!roster.equals(logged))
		{
			logged = roster;
			devLog.log("bingo roster: {}", roster);
		}
	}

	private void set(Map<String, Team> next, Instant end)
	{
		endsAt = end;
		if (next.equals(teams))
		{
			return;
		}
		teams = next;
		listeners.forEach(Runnable::run);
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Bingo;
import com.pvknee.data.Block;
import com.pvknee.ui.Card;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Section;
import com.pvknee.ui.SectionHeader;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import com.pvknee.ui.TileGrid;
import java.awt.BorderLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * The viewed team's bingo board: a tile per place, coloured by the team's progress, with a legend under it, and the
 * selected tile's details under that. Clicking a tile selects it for every bingo block on the page; clicking it
 * again clears the selection.
 */
class BingoBoardBlock implements BlockRenderer
{
	private static final int INNER_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;
	private static final int LEGEND_GAP = 8;
	private static final int CARD_GAP = 6;

	@Override
	public JComponent render(Block block, BlockContext context)
	{
		BingoView view = context.getBingoView();
		Bingo bingo = view.getBingo();
		if (bingo == null || view.getTeam() == null)
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		if (bingo.getTiles().isEmpty())
		{
			return new Section(new SectionHeader(block.setting("title", "Board"), colours), placeholder(bingo, context));
		}
		SectionHeader header = new SectionHeader(block.setting("title", "Board"), colours)
			.withAside(() -> "Select a tile", colours);
		JPanel cards = new JPanel(new BorderLayout(0, CARD_GAP));
		cards.setOpaque(false);
		cards.add(board(view, bingo, context), BorderLayout.NORTH);
		cards.add(context.followBingo(() -> BingoTileDetail.of(bingo, view.getTeam(), view.getTile(), context)), BorderLayout.CENTER);
		return new Section(header, cards);
	}

	/**
	 * Two rows of empty places, until the endpoint sends the tiles at the start.
	 */
	private static Card placeholder(Bingo bingo, BlockContext context)
	{
		int size = Math.max(1, bingo.getBoardSize());
		TileGrid grid = new TileGrid(size, Collections.nCopies(2 * size, null), -1, context.getColours().getAccent(), INNER_WIDTH, index ->
		{
		});
		Card card = new Card(new BorderLayout(0, LEGEND_GAP));
		card.add(grid, BorderLayout.CENTER);
		card.add(Labels.label("The board is revealed when the bingo starts.", context.getColours().getMuted(),
			FontManager.getRunescapeSmallFont(), INNER_WIDTH, true), BorderLayout.SOUTH);
		return card;
	}

	/**
	 * The grid and legend. Built once and changed in place when the team or tile changes, so the board doesn't
	 * flicker.
	 */
	private static Card board(BingoView view, Bingo bingo, BlockContext context)
	{
		int size = Math.max(1, bingo.getBoardSize());
		List<Bingo.Tile> places = new ArrayList<>();
		for (int num = 1; num <= size * size; num++)
		{
			places.add(bingo.tile(num));
		}

		TileGrid grid = new TileGrid(size, gridTiles(view, places), selectedIndex(view, places), context.getColours().getAccent(), INNER_WIDTH,
			index -> view.selectTile(places.get(index) == view.getTile() ? null : places.get(index)));
		view.onChange(() -> grid.setTiles(gridTiles(view, places), selectedIndex(view, places)));
		int iconSize = TileGrid.iconSize(INNER_WIDTH, size);
		for (int i = 0; i < places.size(); i++)
		{
			Bingo.Tile tile = places.get(i);
			int index = i;
			if (tile != null)
			{
				context.getIcons().loadItem(tile.getItemId(), iconSize, icon -> grid.setIcon(index, icon.getImage()));
			}
		}

		Card card = new Card(new BorderLayout(0, LEGEND_GAP));
		card.add(grid, BorderLayout.CENTER);
		card.add(TileGrid.legend(context.getColours().getMuted()), BorderLayout.SOUTH);
		return card;
	}

	/**
	 * Each place's look from the viewed team's progress; null for a place without a tile.
	 */
	private static List<TileGrid.Tile> gridTiles(BingoView view, List<Bingo.Tile> places)
	{
		Map<Integer, Bingo.Progress> progress = view.getTeam().getProgress().stream()
			.collect(Collectors.toMap(Bingo.Progress::getNum, Function.identity(), (a, b) -> a));
		List<TileGrid.Tile> tiles = new ArrayList<>();
		for (Bingo.Tile tile : places)
		{
			tiles.add(tile == null ? null : gridTile(tile, progress.get(tile.getNum())));
		}
		return tiles;
	}

	private static int selectedIndex(BingoView view, List<Bingo.Tile> places)
	{
		Bingo.Tile selected = view.getTile();
		return selected == null ? -1 : places.indexOf(selected);
	}

	/**
	 * A tile's look from the team's progress on it, with its name and, when it needs more than one, how much is in
	 * as the hover text, e.g. "Two Bandos pieces · 1 / 2 pieces".
	 */
	private static TileGrid.Tile gridTile(Bingo.Tile tile, Bingo.Progress progress)
	{
		long needed = Math.max(1, tile.getNeeded());
		long amount = progress == null ? 0 : Math.min(progress.getAmount(), needed);
		TileGrid.Status status = progress == null ? TileGrid.Status.NOT_STARTED
			: progress.getStatus() == Bingo.Status.DONE ? TileGrid.Status.DONE
			: TileGrid.Status.PROGRESS;

		String name = tile.getName() == null ? "Tile " + tile.getNum() : tile.getName();
		String tooltip = needed > 1 ? name + " · " + Labels.fraction(amount, needed, tile.getUnit()) : name;
		return new TileGrid.Tile(status, (double) amount / needed, tooltip);
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Bingo;
import com.pvknee.data.Block;
import com.pvknee.player.PlayerState;
import com.pvknee.ui.Labels;
import com.pvknee.ui.RankTable;
import com.pvknee.ui.Section;
import com.pvknee.ui.SectionHeader;
import com.pvknee.ui.ThemeColours;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.swing.JComponent;

/**
 * The viewed bingo team's members: name, tiles they helped complete and points, best first, with the member's own
 * row highlighted. The points column is left out with points=false, or when the endpoint stops sending points.
 */
class BingoMembersBlock implements BlockRenderer
{
	@Override
	public JComponent render(Block block, BlockContext context)
	{
		BingoView view = context.getBingoView();
		if (view.getBingo() == null || view.getTeam() == null)
		{
			return null;
		}

		boolean points = block.booleanSetting("points", true) && view.getBingo().getTeams().stream()
			.flatMap(team -> team.getMembers().stream())
			.anyMatch(member -> member.getPoints() != null);
		ThemeColours colours = context.getColours();
		String title = block.setting("title", null);
		SectionHeader header = title == null ? null : new SectionHeader(title, colours);
		if (header != null && points)
		{
			header.withAside(() -> "Points", colours);
		}
		return new Section(header, context.followBingo(() -> table(view.getTeam(), points, context.getPlayer(), colours)));
	}

	private static JComponent table(Bingo.Team team, boolean points, PlayerState player, ThemeColours colours)
	{
		List<Bingo.Member> members = team.getMembers().stream()
			.filter(member -> member.getName() != null)
			.sorted(Comparator.comparing((Bingo.Member member) -> Objects.requireNonNullElse(member.getPoints(), 0.0)).reversed())
			.collect(Collectors.toList());
		if (members.isEmpty())
		{
			return null;
		}

		RankTable table = new RankTable(colours);
		for (Bingo.Member member : members)
		{
			boolean you = player.isNamed(member.getName());
			table.addRow(RankTable.Row.builder()
				.name(member.getName())
				.suffix(you ? "(you)" : null)
				.caption(member.getTiles() + (member.getTiles() == 1 ? " tile" : " tiles"))
				.value(points && member.getPoints() != null ? Labels.decimal(member.getPoints()) : null)
				.highlight(you)
				.build());
		}
		return table;
	}
}

package com.pvknee.blocks;

import com.pvknee.bingo.TeamColours;
import com.pvknee.data.Bingo;
import com.pvknee.data.Block;
import com.pvknee.player.PlayerState;
import com.pvknee.ui.Card;
import com.pvknee.ui.Centred;
import com.pvknee.ui.Divider;
import com.pvknee.ui.Dots;
import com.pvknee.ui.EmptyState;
import com.pvknee.ui.Fonts;
import com.pvknee.ui.GlyphIcon;
import com.pvknee.ui.Glyphs;
import com.pvknee.ui.IconButton;
import com.pvknee.ui.Labels;
import com.pvknee.ui.PlacePill;
import com.pvknee.ui.ProgressBar;
import com.pvknee.ui.RankBadge;
import com.pvknee.ui.Section;
