import com.pvknee.ui.ThemeColours;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.time.Duration;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * The bingo team being viewed: a switcher through every team's board, its rank, tiles done and points, a bar of tiles
 * done (left out before the start), and its members' names in two columns. The title's aside is the time until the start, the
 * time left, or "Ended". Above it, while the bingo runs, a note for members who are logged out or not on a team, and
 * once it has ended, the result: "Tallying results" until the admins finish, then the winner.
 */
class BingoTeamBlock implements BlockRenderer
{
	private static final int INNER_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;
	private static final int ROW_GAP = 8;
	private static final int SWITCHER_GAP = 6;
	private static final int TROPHY_SIZE = 28;
	private static final float WINNER_SIZE = 17f;
	private static final int RESULT_GAP = 6;
	private static final int MEMBER_COLUMN_GAP = 10;
	/** Inside each member's name, so the member's own highlight reaches past the text. */
	private static final int MEMBER_PADDING_X = 4;
	private static final int MEMBER_PADDING_Y = 3;
	/** The strength of the accent tint behind the member's own name, out of 255. */
	private static final int OWN_TINT = 26;

	@Override
	public JComponent render(Block block, BlockContext context)
	{
		BingoView view = context.getBingoView();
		Bingo bingo = view.getBingo();
		if (bingo == null || view.getTeam() == null)
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		Instant start = Times.parse(bingo.getStartsAt());
		Instant end = Times.parse(bingo.getEndsAt());
		SectionHeader header = new SectionHeader(title(view), colours)
			.withTimeAside(() -> time(start, end), () -> started(start) && end != null && Times.endingSoon(end), colours);
		context.onUpdate(header::update);
		view.onChange(() -> header.setTitle(title(view)));
		Section team = new Section(header, context.followBingo(() -> card(view, bingo, context.getPlayer(), colours)));

		JComponent above = above(view, bingo, end, context);
		if (above == null)
		{
			return team;
		}
		JPanel stack = new JPanel(new BorderLayout(0, Spacing.BLOCK_GAP));
		stack.setOpaque(false);
		stack.add(above, BorderLayout.NORTH);
		stack.add(team, BorderLayout.CENTER);
		return stack;
	}

	/**
	 * What goes above the team card: the result once the bingo has ended, otherwise a note when the member is logged
	 * out or not on a team. Null for nothing.
	 */
	private static JComponent above(BingoView view, Bingo bingo, Instant end, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		Bingo.State state = bingo.getState();
		if (state == Bingo.State.TALLYING || state == Bingo.State.FINAL)
		{
			SectionHeader header = new SectionHeader("Result", colours)
				.withAside(() -> end == null ? "" : "Ended " + Times.date(end, false), colours);
			return new Section(header, state == Bingo.State.TALLYING
				? new EmptyState(Glyphs.HOURGLASS, "Tallying results", "Points below may still change.", colours)
				: result(view, bingo, colours));
		}
		if (!context.getPlayer().isLoggedIn())
		{
			return new EmptyState(Glyphs.USER, "Log in to see your team", "The teams and their points still show below.", colours);
		}
		if (view.getOwnTeam() == null)
		{
			return new EmptyState(Glyphs.GROUP, "You're not on a team", "Ask an admin to add you. You can still follow the teams below.", colours);
		}
		return null;
	}

	/**
	 * The final result: a trophy, "[Team] won" with its points and tiles, then the member's own team's place.
	 */
	private static Card result(BingoView view, Bingo bingo, ThemeColours colours)
	{
		List<Bingo.Team> winners = bingo.getTeams().stream()
			.filter(team -> team.getRank() == 1)
			.collect(Collectors.toList());
		if (winners.isEmpty())
		{
			winners = bingo.getTeams().subList(0, 1);
		}
		Color gold = RankBadge.medalColour(1);
		int total = bingo.getBoardSize() * bingo.getBoardSize();

		Card card = new Card(new DynamicGridLayout(0, 1, 0, RESULT_GAP));
		card.add(new JLabel(new GlyphIcon(Glyphs.TROPHY, gold, TROPHY_SIZE)));
		String names = winners.stream().map(team -> Objects.toString(team.getName(), "")).collect(Collectors.joining(" & "));
		card.add(Labels.label(names + " won", gold, Fonts.boldName().deriveFont(WINNER_SIZE), INNER_WIDTH, true));
		Bingo.Team winner = winners.get(0);
		card.add(Labels.label(Labels.decimal(winner.getPoints()) + " pts · " + winner.getTilesDone() + " of " + total + " tiles",
			colours.getMuted(), FontManager.getRunescapeSmallFont(), INNER_WIDTH, true));

		Bingo.Team own = view.getOwnTeam();
		if (own != null)
		{
			card.add(new Divider(colours.getMuted()));
			JPanel row = new JPanel(new BorderLayout(ROW_GAP, 0));
			row.setOpaque(false);
			JLabel yours = Labels.plain("Your team, " + own.getName(), ThemeColours.TEXT, FontManager.getRunescapeSmallFont());
			row.add(yours, BorderLayout.CENTER);
			JLabel place = Labels.plain(Labels.ordinal(own.getRank()) + " · " + Labels.decimal(own.getPoints()) + " pts",
				colours.getValue(), FontManager.getRunescapeSmallFont());
			row.add(place, BorderLayout.EAST);
			card.add(row);
		}
		return card;
	}

	private static String title(BingoView view)
	{
		return view.isOwnTeam(view.getTeam()) ? "Your Team" : "Team";
	}

	/**
	 * e.g. "Starts in 2d 4h", "12d 20h left" or "Ended".
	 */
	private static String time(Instant start, Instant end)
	{
		Instant now = Instant.now();
		if (!started(start))
		{
			return "Starts in " + Times.duration(Duration.between(now, start));
		}
		if (end == null)
		{
			return "";
		}
		return now.isBefore(end) ? Times.left(end) : "Ended";
	}

	private static boolean started(Instant start)
	{
		return start == null || !Instant.now().isBefore(start);
	}

	private static Card card(BingoView view, Bingo bingo, PlayerState player, ThemeColours colours)
	{
		Bingo.Team team = view.getTeam();
		int total = bingo.getBoardSize() * bingo.getBoardSize();

		Card card = new Card(new DynamicGridLayout(0, 1, 0, ROW_GAP));
		card.add(switcher(view, bingo.getTeams(), team, colours));
		if (bingo.getState() != Bingo.State.UPCOMING)
		{
			card.add(standing(team, total, colours));
			card.add(new ProgressBar(total == 0 ? 0 : (double) team.getTilesDone() / total, ThemeColours.DONE));
		}
		if (!team.getMembers().isEmpty())
		{
			card.add(new Divider(colours.getMuted()));
			card.add(members(team, player, colours));
		}
		return card;
	}

	/**
	 * A muted "Members" label with the count, then the names in two columns in sheet order, the member's own name
	 * with a soft accent tint. A name too wide for its column is cut short and shows in full on hover.
	 */
	private static JComponent members(Bingo.Team team, PlayerState player, ThemeColours colours)
	{
		JPanel heading = new JPanel(new BorderLayout());
		heading.setOpaque(false);
		heading.setBorder(new EmptyBorder(0, MEMBER_PADDING_X, 0, MEMBER_PADDING_X));
		heading.add(muted("Members", colours), BorderLayout.WEST);
		heading.add(muted(String.valueOf(team.getMembers().size()), colours), BorderLayout.EAST);

		int nameWidth = (INNER_WIDTH - MEMBER_COLUMN_GAP) / 2 - 2 * MEMBER_PADDING_X;
		Color tint = colours.getAccent();
		JPanel names = new JPanel(new GridLayout(0, 2, MEMBER_COLUMN_GAP, 1));
		names.setOpaque(false);
		for (Bingo.Member member : team.getMembers())
		{
			String name = Objects.toString(member.getName(), "");
			boolean own = player.isNamed(name);
			Card cell = new Card(new BorderLayout(), false);
			cell.setBorder(new EmptyBorder(MEMBER_PADDING_Y, MEMBER_PADDING_X, MEMBER_PADDING_Y, MEMBER_PADDING_X));
			cell.setArc(Spacing.CONTROL_ARC);
			cell.setBackground(own ? new Color(tint.getRed(), tint.getGreen(), tint.getBlue(), OWN_TINT) : new Color(0, 0, 0, 0));

			JLabel label = Labels.plain(name, own ? colours.getValue() : ThemeColours.TEXT, Fonts.name());
			if (label.getPreferredSize().width > nameWidth)
			{
				Labels.tooltip(label, name);
			}
			cell.add(label, BorderLayout.CENTER);
			names.add(cell);
		}

		JPanel section = new JPanel(new BorderLayout(0, 2));
		section.setOpaque(false);
		section.add(heading, BorderLayout.NORTH);
		section.add(names, BorderLayout.CENTER);
		return section;
	}

	private static JLabel muted(String text, ThemeColours colours)
	{
		return Labels.plain(text, colours.getMuted(), FontManager.getRunescapeSmallFont());
	}

	/**
	 * The team's name with a dot per team under it, between arrows that step through the teams in place order (1st
	 * first) and wrap around, so flicking through it is the standings. The dots are in the same order, coloured by
	 * place. Just the name when there is only one team.
	 */
	private static JComponent switcher(BingoView view, List<Bingo.Team> all, Bingo.Team team, ThemeColours colours)
	{
		List<Bingo.Team> teams = all.stream()
			.sorted(Comparator.comparingInt(t -> t.getRank() >= 1 ? t.getRank() : Integer.MAX_VALUE))
			.collect(Collectors.toList());
		int count = teams.size();
		int index = teams.indexOf(team);
		int nameWidth = count > 1 ? INNER_WIDTH - 2 * (IconButton.SMALL_SIZE + SWITCHER_GAP) : INNER_WIDTH;

		JPanel middle = new JPanel(new BorderLayout(0, Spacing.ITEM_GAP));
		middle.setOpaque(false);
		middle.add(Labels.clamped(Objects.toString(team.getName(), ""), TeamColours.of(all, team),
			Fonts.boldName(), nameWidth, true, Labels.NAME_LINES), BorderLayout.CENTER);

		JPanel row = new JPanel(new BorderLayout(SWITCHER_GAP, 0));
		row.setOpaque(false);
		row.add(middle, BorderLayout.CENTER);
		if (count > 1)
		{
			List<Color> places = teams.stream().map(t -> RankBadge.placeColour(t.getRank())).collect(Collectors.toList());
			middle.add(new Dots(places, index), BorderLayout.SOUTH);
			row.add(new Centred(new IconButton(Glyphs.CHEVRON_LEFT, "Previous team",
				() -> view.selectTeam(teams.get((index + count - 1) % count))).small()), BorderLayout.WEST);
			row.add(new Centred(new IconButton(Glyphs.CHEVRON_RIGHT, "Next team",
				() -> view.selectTeam(teams.get((index + 1) % count))).small()), BorderLayout.EAST);
		}
		return row;
	}

	/**
	 * The rank badge, e.g. "9 of 36 tiles", and the points.
	 */
	private static JComponent standing(Bingo.Team team, int total, ThemeColours colours)
	{
		int rank = team.getRank();
		JPanel row = new JPanel(new BorderLayout(ROW_GAP, 0));
		row.setOpaque(false);
		if (rank >= 1)
		{
			row.add(new Centred(new PlacePill(rank)), BorderLayout.WEST);
		}

		JLabel tiles = Labels.plain(team.getTilesDone() + " of " + total + " tiles", colours.getMuted(), FontManager.getRunescapeSmallFont());
		row.add(tiles, BorderLayout.CENTER);

		JLabel points = Labels.plain(Labels.decimal(team.getPoints()) + " pts", colours.getValue(), Fonts.boldName());
		row.add(points, BorderLayout.EAST);
		return row;
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Bingo;
import com.pvknee.data.Block;
import com.pvknee.ui.Labels;
import com.pvknee.ui.RankBadge;
import com.pvknee.ui.RankTable;
import com.pvknee.ui.Section;
import com.pvknee.ui.SectionHeader;
import com.pvknee.ui.ThemeColours;
import javax.swing.JComponent;

/**
 * Every bingo team's standing: medal badges for the top places, the team's name, tiles done and points, with the
 * member's own team highlighted and the team being viewed outlined. Clicking a team shows its board.
 */
class BingoTeamsBlock implements BlockRenderer
{
	@Override
	public JComponent render(Block block, BlockContext context)
	{
		BingoView view = context.getBingoView();
		Bingo bingo = view.getBingo();
		if (bingo == null || bingo.getTeams().isEmpty())
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		String title = block.setting("title", null);
		SectionHeader header = title == null ? null : new SectionHeader(title, colours).withAside(() -> "Points", colours);
		return new Section(header, context.followBingo(() -> table(view, bingo, colours)));
	}

	private static RankTable table(BingoView view, Bingo bingo, ThemeColours colours)
	{
		RankTable table = new RankTable(colours);
		for (Bingo.Team team : bingo.getTeams())
		{
			int rank = team.getRank();
			table.addRow(RankTable.Row.builder()
				.rank(rank)
				.medal(rank >= 1 && rank <= RankBadge.medalPlaces())
				.name(team.getName())
				.caption(team.getTilesDone() + (team.getTilesDone() == 1 ? " tile" : " tiles"))
				.value(Labels.decimal(team.getPoints()))
				.highlight(view.isOwnTeam(team))
				.outline(team == view.getTeam() ? colours.getAccent() : null)
				.onClick(() -> view.selectTeam(team))
				.build());
		}
		return table;
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Bingo;
import com.pvknee.ui.Card;
import com.pvknee.ui.Centred;
import com.pvknee.ui.CheckMark;
import com.pvknee.ui.Divider;
import com.pvknee.ui.Fonts;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Pill;
import com.pvknee.ui.ProgressBar;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import java.awt.BorderLayout;
import java.awt.Color;
import java.time.Instant;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * The card under the bingo board for the selected tile: what it needs and the viewed team's progress on it. A dashed
 * hint when no tile is selected.
 */
final class BingoTileDetail
{
	private static final int INNER_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;
	private static final int ICON_SIZE = 26;
	private static final int PART_ICON_SIZE = 16;
	private static final int MARK_SIZE = 14;
	private static final int ROW_GAP = 8;
	private static final int HEAD_GAP = 10;

	private BingoTileDetail()
	{
	}

	static Card of(Bingo bingo, Bingo.Team team, Bingo.Tile tile, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		if (tile == null)
		{
			Card hint = new Card(new BorderLayout());
			hint.setDashed(true);
			hint.add(small("Select a tile to view it", colours.getMuted(), true));
			return hint;
		}

		Bingo.Progress progress = team.getProgress().stream()
			.filter(p -> p.getNum() == tile.getNum())
			.findFirst()
			.orElse(null);

		Card card = new Card(new DynamicGridLayout(0, 1, 0, ROW_GAP));
		card.add(head(tile, progress != null && progress.getStatus() == Bingo.Status.DONE, context));
		if (tile.getDescription() != null && !tile.getDescription().trim().isEmpty())
		{
			card.add(Labels.label(tile.getDescription(), ThemeColours.TEXT, Fonts.body(), INNER_WIDTH, false));
		}
		card.add(new Divider(colours.getMuted()));

		if (progress == null)
		{
			notStarted(card, bingo, colours);
		}
		else if (progress.getStatus() == Bingo.Status.DONE)
		{
			done(card, tile, progress, colours);
		}
		else
		{
			inProgress(card, tile, progress, context);
		}
		return card;
	}

	/**
	 * The icon, name and tile number, and the points pill; the name and points are green once the tile is done.
	 */
	private static JComponent head(Bingo.Tile tile, boolean done, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		Color highlight = done ? ThemeColours.DONE : colours.getValue();
		Pill pill = new Pill("+" + Labels.decimal(tile.getPoints()), highlight, null).bold();
		int textWidth = INNER_WIDTH - ICON_SIZE - pill.getPreferredSize().width - 2 * HEAD_GAP;

		JPanel text = new JPanel(new BorderLayout(0, 1));
		text.setOpaque(false);
		text.add(Labels.label(Objects.toString(tile.getName(), ""), highlight, Fonts.boldName(), textWidth, false), BorderLayout.CENTER);
		text.add(small("Tile " + tile.getNum(), colours.getMuted(), false), BorderLayout.SOUTH);

		JPanel head = new JPanel(new BorderLayout(HEAD_GAP, 0));
		head.setOpaque(false);
		head.add(context.getIcons().item(tile.getItemId(), ICON_SIZE), BorderLayout.WEST);
		head.add(text, BorderLayout.CENTER);
		head.add(new Centred(pill), BorderLayout.EAST);
		return head;
	}

	private static void notStarted(Card card, Bingo bingo, ThemeColours colours)
	{
		String submit = bingo.getSubmit() == null || bingo.getSubmit().trim().isEmpty() ? "" : " in " + bingo.getSubmit().trim();
		card.add(Labels.plain("Not started", colours.getMuted(), FontManager.getRunescapeBoldFont()));
		card.add(small("Got it? Post a screenshot" + submit + " on Discord.", colours.getMuted(), false));
	}

	/**
	 * "Completed" with the points, then when and by whom, e.g. "Sun 1 Nov, 19:12 · by Iron Aeria".
	 */
	private static void done(Card card, Bingo.Tile tile, Bingo.Progress progress, ThemeColours colours)
	{
		card.add(statusLine("Completed", ThemeColours.DONE, "+" + Labels.decimal(tile.getPoints()) + " pts", ThemeColours.DONE));

		Instant at = Times.parse(progress.getCompletedAt());
		String when = at == null ? null : Times.date(at, true);
		String by = progress.getCompletedBy();
		String line = when != null && by != null ? when + " · by " + by
			: when != null ? when
			: by != null ? "By " + by
			: null;
		if (line != null)
		{
			card.add(small(line, colours.getMuted(), false));
		}
	}

	/**
	 * "In progress" with how much is in and a bar, then who got what, or for a tile with parts, a checklist of parts.
	 */
	private static void inProgress(Card card, Bingo.Tile tile, Bingo.Progress progress, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		long needed = Math.max(1, tile.getNeeded());
		long amount = Math.min(progress.getAmount(), needed);
		card.add(statusLine("In progress", ThemeColours.IN_PROGRESS, Labels.fraction(amount, needed, tile.getUnit()), colours.getValue()));
		card.add(new ProgressBar((double) amount / needed, ThemeColours.IN_PROGRESS));

		if (tile.getParts().isEmpty())
		{
			for (Bingo.Contributor contributor : progress.getContributors())
			{
				String note = contributor.getNote();
				String what = note != null && !note.trim().isEmpty() ? note.trim() : Labels.amount(contributor.getAmount(), tile.getUnit());
				card.add(row(null, contributor.getName(), what, colours));
			}
			return;
		}

		Map<String, Bingo.PartProgress> parts = progress.getParts().stream()
			.filter(part -> part.getName() != null)
			.collect(Collectors.toMap(Bingo.PartProgress::getName, Function.identity(), (a, b) -> a));
		for (Bingo.Part part : tile.getParts())
		{
			card.add(partRow(part, parts.get(part.getName()), context));
		}
	}

	/**
	 * A part's icon, a tick when it is in (or how much, e.g. "1 / 2", when it needs more than one), its name and who
	 * got it.
	 */
	private static JComponent partRow(Bingo.Part part, Bingo.PartProgress progress, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		boolean done = progress != null && progress.isDone();
		long needed = Math.max(1, part.getNeeded());

		JPanel lead = new JPanel(new BorderLayout(Spacing.ITEM_GAP, 0));
		lead.setOpaque(false);
		if (part.getItemId() > 0)
		{
			lead.add(context.getIcons().item(part.getItemId(), PART_ICON_SIZE), BorderLayout.WEST);
		}
		lead.add(done || needed == 1 ? new JLabel(new CheckMark(done, MARK_SIZE))
			: Labels.plain((progress == null ? 0 : progress.getAmount()) + " / " + needed, colours.getMuted(), FontManager.getRunescapeSmallFont()),
			BorderLayout.CENTER);

		String who = progress == null ? "" : progress.getContributors().stream()
			.map(Bingo.Contributor::getName)
			.filter(Objects::nonNull)
			.distinct()
			.collect(Collectors.joining(", "));
		return row(lead, part.getName(), who, colours);
	}

	/**
	 * A name on the left, after an optional lead, with a muted note on the right.
	 */
	private static JComponent row(JComponent lead, String name, String note, ThemeColours colours)
	{
		JPanel row = new JPanel(new BorderLayout(ROW_GAP, 0));
		row.setOpaque(false);
		if (lead != null)
		{
			row.add(lead, BorderLayout.WEST);
		}
		row.add(Labels.plain(Objects.toString(name, ""), ThemeColours.TEXT, Fonts.name()), BorderLayout.CENTER);
		row.add(Labels.plain(note, colours.getMuted(), FontManager.getRunescapeSmallFont()), BorderLayout.EAST);
		return row;
	}

	/**
	 * The status in its colour on the left, with a value on the right.
	 */
	private static JComponent statusLine(String status, Color colour, String value, Color valueColour)
	{
		JPanel row = new JPanel(new BorderLayout(ROW_GAP, 0));
		row.setOpaque(false);
		row.add(Labels.plain(status, colour, FontManager.getRunescapeBoldFont()), BorderLayout.WEST);
		row.add(Labels.plain(value, valueColour, FontManager.getRunescapeSmallFont()), BorderLayout.EAST);
		return row;
	}

	private static JLabel small(String text, Color colour, boolean centred)
	{
		return Labels.label(text, colour, FontManager.getRunescapeSmallFont(), INNER_WIDTH, centred);
	}
}

package com.pvknee.blocks;

import com.pvknee.DevLog;
import com.pvknee.data.Bingo;
import com.pvknee.player.PlayerState;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * What the bingo page is showing: the selected team and tile, shared by every bingo block on the page so they follow
 * the same selection. Kept while the data reloads and the page is built again. Used on the Swing thread.
 */
public class BingoView
{
	private final DevLog devLog;
	private final List<Runnable> listeners = new ArrayList<>();

	private Bingo bingo;
	private Bingo.Team ownTeam;
	/** The team the member switched to; null to follow their own team (or the top team). */
	private String chosenTeam;
	private Integer selectedTile;
	/** The last state logged, so a reload that changes nothing logs nothing. */
	private String logged;

	public BingoView(DevLog devLog)
	{
		this.devLog = devLog;
	}

	/**
	 * Takes in new data or a change in game, keeping the selection while its team and tile still exist.
	 */
	public void update(Bingo bingo, PlayerState player)
	{
		this.bingo = bingo;
		ownTeam = bingo == null ? null : bingo.getTeams().stream()
			.filter(team -> team.getMembers().stream().anyMatch(member -> player.isNamed(member.getName())))
			.findFirst()
			.orElse(null);
		if (bingo == null || bingo.team(chosenTeam) == null)
		{
			chosenTeam = null;
		}
		if (bingo == null || selectedTile != null && bingo.tile(selectedTile) == null)
		{
			selectedTile = null;
		}

		String state = bingo == null ? "none"
			: bingo.getState() + ", own team " + name(ownTeam) + ", viewing " + name(getTeam()) + ", tile " + (selectedTile == null ? "none" : selectedTile);
		if (!state.equals(logged))
		{
			logged = state;
			devLog.log("bingo: {}", state);
		}
	}

	/**
	 * The bingo, or null if there is none.
	 */
	public Bingo getBingo()
	{
		return bingo;
	}

	/**
	 * The member's own team; null when logged out or not on a team.
	 */
	public Bingo.Team getOwnTeam()
	{
		return ownTeam;
	}

	public boolean isOwnTeam(Bingo.Team team)
	{
		return team != null && team == ownTeam;
	}

	/**
	 * The team being viewed: the one the member switched to, else their own, else the top team. Null with no teams.
	 */
	public Bingo.Team getTeam()
	{
		if (bingo == null)
		{
			return null;
		}

		Bingo.Team chosen = bingo.team(chosenTeam);
		if (chosen != null)
		{
			return chosen;
		}
		if (ownTeam != null)
		{
			return ownTeam;
		}
		return bingo.getTeams().isEmpty() ? null : bingo.getTeams().get(0);
	}

	public void selectTeam(Bingo.Team team)
	{
		if (team == null || team == getTeam())
		{
			return;
		}

		chosenTeam = team == ownTeam ? null : team.getName();
		devLog.log("bingo: viewing {}", team.getName());
		changed();
	}

	/**
	 * The selected tile, or null.
	 */
	public Bingo.Tile getTile()
	{
		return bingo == null || selectedTile == null ? null : bingo.tile(selectedTile);
	}

	/**
	 * Selects the tile, or clears the selection with null.
	 */
	public void selectTile(Bingo.Tile tile)
	{
		Integer num = tile == null ? null : tile.getNum();
		if (Objects.equals(num, selectedTile))
		{
			return;
		}

		selectedTile = num;
		devLog.log("bingo: tile {}", num == null ? "cleared" : num + " selected");
		changed();
	}

	/**
	 * Runs after the selected team or tile changes, until the page is built again.
	 */
	public void onChange(Runnable listener)
	{
		listeners.add(listener);
	}

	/**
	 * Forgets the listeners of the page that was shown, before the next is built.
	 */
	public void clearListeners()
	{
		listeners.clear();
	}

	private void changed()
	{
		new ArrayList<>(listeners).forEach(Runnable::run);
	}

	private static String name(Bingo.Team team)
	{
		return team == null ? "none" : team.getName();
	}
}

