package com.pvknee.blocks;

import com.pvknee.data.Block;
import com.pvknee.data.Competition;
import com.pvknee.data.Competitions;
import com.pvknee.ui.Card;
import com.pvknee.ui.Divider;
import com.pvknee.ui.Fonts;
import com.pvknee.ui.IconCaption;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Section;
import com.pvknee.ui.SectionHeader;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import com.pvknee.ui.TimeBar;
import java.awt.BorderLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import javax.swing.border.EmptyBorder;

class CompetitionBlock implements BlockRenderer
{
	private static final int SIDE_ICON_SIZE = 32;
	private static final int HERO_ICON_SIZE = 48;
	private static final float HERO_NAME_SIZE = 20f;
	private static final int INNER_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;

	@Override
	public JComponent render(Block block, BlockContext context)
	{
		boolean upcoming = block.setting("which", "current").equalsIgnoreCase("upcoming");
		String type = block.setting("type", "all").toLowerCase();

		Competitions competitions = context.getData().getCompetitions();
		List<Competition> source = competitions == null ? null : upcoming ? competitions.getUpcoming() : competitions.getCurrent();
		if (source == null)
		{
			return null;
		}

		List<Competition> matching = source.stream()
			.filter(c -> c.getName() != null)
			.filter(c -> type.equals("all") || type.equalsIgnoreCase(c.getType()))
			.collect(Collectors.toList());
		if (matching.isEmpty())
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		String title = block.setting("title", null);
		if (block.setting("layout", "side").equalsIgnoreCase("hero"))
		{
			return Section.titled(title, hero(matching.get(0), upcoming, block, context), colours);
		}

		SectionHeader header = null;
		if (title != null)
		{
			header = new SectionHeader(title, colours);
			Competition first = matching.get(0);
			Instant time = Times.parse(upcoming ? first.getStartsAt() : first.getEndsAt());
			if (time != null)
			{
				header.withTimeAside(
					upcoming ? () -> Times.date(time, true) : () -> Times.left(time),
					() -> !upcoming && Times.endingSoon(time),
					colours);
				context.onUpdate(header::update);
			}
		}
		return new Section(header, side(matching, block, context));
	}

	/**
	 * One clickable column per competition, with thin dividers between them. The weekly competitions always share
	 * their times, so the time is the title's aside rather than part of the card.
	 */
	private static Card side(List<Competition> competitions, Block block, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		int count = competitions.size();
		int dividerWidth = 1 + 2 * Spacing.ITEM_GAP;
		int columnWidth = (INNER_WIDTH - dividerWidth * (count - 1)) / count - 2 * Spacing.ITEM_GAP;

		Card card = new Card(new GridBagLayout());
		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = 0;
		constraints.gridy = 0;
		constraints.fill = GridBagConstraints.BOTH;
		constraints.weighty = 1;
		for (Competition competition : competitions)
		{
			if (constraints.gridx > 0)
			{
				constraints.weightx = 0;
				constraints.insets = new Insets(Spacing.ITEM_GAP, Spacing.ITEM_GAP, Spacing.ITEM_GAP, Spacing.ITEM_GAP);
				card.add(Divider.vertical(colours.getMuted()), constraints);
				constraints.gridx++;
			}

			Card column = new Card(new BorderLayout(), false);
			column.setBorder(new EmptyBorder(Spacing.ITEM_GAP, Spacing.ITEM_GAP, Spacing.ITEM_GAP, Spacing.ITEM_GAP));
			context.linkToPage(column, block, competition.getType());
			column.add(new IconCaption(
				kind(competition),
				context.metricIcon(competition.getMetric(), SIDE_ICON_SIZE),
				competition.getName(),
				colours.resolve(competition.getColour(), colours.getValue()),
				columnWidth,
				colours), BorderLayout.NORTH);

			constraints.weightx = 1;
			constraints.insets = new Insets(0, 0, 0, 0);
			card.add(column, constraints);
			constraints.gridx++;
		}
		return card;
	}

	/**
	 * One big competition: icon, name, then a day bar with the end date on the left and the time left on the right
	 * (or for an upcoming one, the start date and the time until it starts, without a bar).
	 */
	private static Card hero(Competition competition, boolean upcoming, Block block, BlockContext context)
	{
		ThemeColours colours = context.getColours();
		Card card = new Card(new BorderLayout(0, Spacing.TITLE_GAP));
		context.linkToPage(card, block, competition.getType());
		card.add(new IconCaption(
			null,
			context.metricIcon(competition.getMetric(), HERO_ICON_SIZE),
			competition.getName(),
			colours.resolve(competition.getColour(), colours.getValue()),
			Fonts.boldName().deriveFont(HERO_NAME_SIZE),
			INNER_WIDTH,
			colours), BorderLayout.NORTH);

		Instant start = Times.parse(competition.getStartsAt());
		Instant end = Times.parse(competition.getEndsAt());
		if (upcoming && start != null)
		{
			TimeBar bar = new TimeBar(null, Times.date(start, true),
				() -> "Starts in " + Times.duration(Duration.between(Instant.now(), start)), null, colours);
			context.onUpdate(bar::update);
			card.add(bar, BorderLayout.SOUTH);
		}
		else if (!upcoming && start != null && end != null)
		{
			card.add(context.runningBar(start, end, Times.date(end, true), true), BorderLayout.SOUTH);
		}
		return card;
	}

	private static String kind(Competition competition)
	{
		String type = Objects.toString(competition.getType(), "");
		if (type.equalsIgnoreCase("skill"))
		{
			return "Skill";
		}
		return type.equalsIgnoreCase("boss") ? "Boss" : null;
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Block;
import com.pvknee.ui.Card;
import com.pvknee.ui.Fonts;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Section;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import com.pvknee.ui.TimeBar;
import java.awt.BorderLayout;
import java.time.Duration;
import java.time.Instant;
import javax.swing.JComponent;
import lombok.extern.slf4j.Slf4j;

/**
 * A label and a live countdown to a date, e.g. "Bingo starts in" with the date on the left and "3d 4h" on the right,
 * in the ending-soon colour in the last 24 hours. Nothing once the date has passed.
 */
@Slf4j
class CountdownBlock implements BlockRenderer
{
	private static final int INNER_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;

	@Override
	public JComponent render(Block block, BlockContext context)
	{
		String label = block.setting("label", null);
		Instant until = Times.parse(block.setting("until", null));
		if (label == null || until == null)
		{
			log.debug("Countdown needs a label and an ISO time: {}", block.getSettings());
			return null;
		}
		if (!Instant.now().isBefore(until))
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		TimeBar time = new TimeBar(null, Times.date(until, true),
			() -> Instant.now().isBefore(until) ? Times.duration(Duration.between(Instant.now(), until)) : "Now",
			() -> Times.endingSoon(until),
			colours);
		context.onUpdate(time::update);

		Card card = new Card(new BorderLayout(0, Spacing.TITLE_GAP));
		card.add(Labels.label(label, colours.getValue(), Fonts.name(), INNER_WIDTH, false), BorderLayout.NORTH);
		card.add(time, BorderLayout.SOUTH);
		return Section.titled(block.setting("title", null), card, colours);
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Block;
import com.pvknee.data.ClanEvent;
import com.pvknee.ui.EntryRow;
import com.pvknee.ui.GlyphIcon;
import com.pvknee.ui.Glyphs;
import com.pvknee.ui.Labels;
import com.pvknee.ui.ListCard;
import com.pvknee.ui.Section;
import com.pvknee.ui.SectionHeader;
import com.pvknee.ui.Spacing;
import com.pvknee.ui.ThemeColours;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import javax.swing.JLabel;
import net.runelite.client.ui.FontManager;

/**
 * Running and upcoming events in one list card. A time every entry shares shows once beside the title; otherwise
 * each entry shows its own. Running entries, and a bingo even before it starts, open the page the block names for
 * their kind (e.g. bingo_page). A block with nothing to show draws nothing.
 */
class EventsBlock implements BlockRenderer
{
	private static final int ROW_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;
	/** Line icons look the same size as pictures when drawn slightly smaller. */
	private static final int GLYPH_SIZE = 18;

	@Override
	public JComponent render(Block block, BlockContext context)
	{
		String when = block.setting("when", "upcoming").toLowerCase();
		boolean both = when.equals("both");
		boolean showRunning = both || when.equals("running");
		boolean showUpcoming = both || !showRunning;
		Set<String> kinds = kinds(block.setting("kind", "all"));

		Instant now = Instant.now();
		List<TimedEvent> running = new ArrayList<>();
		List<TimedEvent> upcoming = new ArrayList<>();
		List<ClanEvent> events = context.getData().getEvents();
		for (ClanEvent event : events == null ? List.<ClanEvent>of() : events)
		{
			TimedEvent timed = new TimedEvent(event, now);
			if (timed.start == null || event.getName() == null || (kinds != null && !kinds.contains(kind(event))))
			{
				continue;
			}
			if (showRunning && timed.running)
			{
				running.add(timed);
			}
			else if (showUpcoming && now.isBefore(timed.start))
			{
				upcoming.add(timed);
			}
		}
		running.sort(Comparator.comparing(e -> e.end == null ? Instant.MAX : e.end));
		upcoming.sort(Comparator.comparing(e -> e.start));

		List<TimedEvent> shown = new ArrayList<>(running);
		shown.addAll(upcoming);
		shown = shown.subList(0, Math.min(shown.size(), Math.max(0, block.intSetting("limit", 4))));
		if (shown.isEmpty())
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		String title = block.setting("title", null);
		TimedEvent first = shown.get(0);
		boolean shared = title != null && first.timeText() != null && shown.stream()
			.map(e -> Arrays.asList(e.running, e.running ? e.end : e.start, e.event.isHasTime()))
			.distinct()
			.count() == 1;

		ListCard card = new ListCard(colours);
		for (TimedEvent event : shown)
		{
			card.addEntry(entry(event, !shared, block, context));
		}

		SectionHeader header = null;
		if (title != null)
		{
			header = new SectionHeader(title, colours);
			if (shared)
			{
				header.withTimeAside(first::timeText, first::endingSoon, colours);
				context.onUpdate(header::update);
			}
		}
		return new Section(header, card);
	}

	private static EntryRow entry(TimedEvent timed, boolean showTime, Block block, BlockContext context)
	{
		ClanEvent event = timed.event;
		ThemeColours colours = context.getColours();
		boolean bingo = kind(event).equals("bingo");
		JComponent icon = event.getMetric() == null || event.getMetric().isEmpty()
			? new JLabel(new GlyphIcon(bingo ? Glyphs.GRID : Glyphs.CALENDAR, colours.getMuted(), GLYPH_SIZE))
			: context.metricIcon(event.getMetric(), EntryRow.ICON_SIZE);

		EntryRow row = new EntryRow(icon, event.getName(), colours.resolve(event.getColour(), colours.getValue()), ROW_WIDTH);
		row.addCaption(caption(event), colours);
		if (showTime && !timed.running)
		{
			row.addLine(context.liveLabel(timed::timeText, colours.getMuted(), FontManager.getRunescapeSmallFont(), row.getTextWidth(), false));
		}

		// The bingo page has its own state for before the start, so an upcoming bingo opens it too.
		if (timed.running || bingo)
		{
			context.linkToPage(row, block, kind(event));
		}
		if (timed.running)
		{
			if (timed.end != null)
			{
				row.setBar(context.runningBar(timed.start, timed.end, null, showTime));
			}
		}
		return row;
	}

	/**
	 * The kinds to show from a comma list, e.g. "event" or "skill, boss"; null for all.
	 */
	private static Set<String> kinds(String setting)
	{
		Set<String> kinds = Arrays.stream(setting.split(","))
			.map(k -> k.trim().toLowerCase(Locale.ENGLISH))
			.filter(k -> !k.isEmpty())
			.collect(Collectors.toSet());
		return kinds.isEmpty() || kinds.contains("all") ? null : kinds;
	}

	/**
	 * The event's kind in lower case; events without one count as "event".
	 */
	private static String kind(ClanEvent event)
	{
		String kind = Objects.toString(event.getKind(), "").trim().toLowerCase(Locale.ENGLISH);
		return kind.isEmpty() ? "event" : kind;
	}

	private static String caption(ClanEvent event)
	{
		switch (kind(event))
		{
			case "skill":
				return "Skill of the Week";
			case "boss":
				return "Boss of the Week";
			case "bingo":
				return "Bingo";
			default:
				return "Event";
		}
	}

	/**
	 * An event with its times worked out. A date-only event (no time of day) covers whole calendar days in the
	 * member's own time zone, from its start day up to the day the sheet's end falls on (or just its start day), so
	 * it shows under the day the sheet has wherever the member is.
	 */
	private static class TimedEvent
	{
		final ClanEvent event;
		final Instant start;
		final Instant end;
		/** The first day of a date-only event; null for an event with a time of day. */
		final LocalDate startDay;
		final boolean running;

		TimedEvent(ClanEvent event, Instant now)
		{
			this.event = event;
			Instant sheetStart = Times.parse(event.getStartsAt());
			Instant sheetEnd = Times.parse(event.getEndsAt());
			if (event.isHasTime() || sheetStart == null)
			{
				startDay = null;
				start = sheetStart;
				end = sheetEnd;
			}
			else
			{
				// The sheet sends the end as midnight UTC after the last day, so that day is the first one not covered.
				startDay = Times.sheetDay(sheetStart);
				LocalDate dayAfter = startDay.plusDays(1);
				LocalDate endDay = sheetEnd == null ? dayAfter : Times.sheetDay(sheetEnd);
				start = Times.startOfDay(startDay);
				end = Times.startOfDay(endDay.isBefore(dayAfter) ? dayAfter : endDay);
			}
			this.running = start != null && !now.isBefore(start) && (end == null || now.isBefore(end));
		}

		/**
		 * e.g. "6d 4h left", "Ends in 5h 12m", "Tomorrow, 17:00" or "Fri 6 Nov". Null for a running event without an
		 * end.
		 */
		String timeText()
		{
			if (running)
			{
				return end == null ? null : Times.left(end);
			}
			return startDay != null ? Times.day(startDay) : Times.date(start, true);
		}

		boolean endingSoon()
		{
			return running && end != null && Times.endingSoon(end);
		}
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Bingo;
import com.pvknee.data.Block;
import com.pvknee.data.Competition;
import com.pvknee.ui.PageHeader;
import com.pvknee.ui.Pill;
import com.pvknee.ui.ThemeColours;
import java.time.Instant;
import javax.swing.JComponent;

/**
 * The top of a page: its title, an optional subtitle or a competition's or the bingo's dates, and an optional pill.
 */
class HeaderBlock implements BlockRenderer
{
	@Override
	public JComponent render(Block block, BlockContext context)
	{
		Bingo bingo = isBingo(block) ? context.getBingoView().getBingo() : null;
		String title = block.setting("title", bingo == null ? null : bingo.getName());
		if (title == null)
		{
			return null;
		}

		ThemeColours colours = context.getColours();
		String pillText = block.setting("pill", null);
		Pill pill = pillText == null ? null
			: new Pill(pillText, colours.getValue(), context.mutedGlyph(block.setting("icon", null), Pill.ICON_SIZE));
		return new PageHeader(title, HeadingBlock.size(block), subtitle(block, context), pill, colours);
	}

	/**
	 * The dates "dates" names (current_skill, current_boss or bingo) if there are any, otherwise the "subtitle"
	 * setting.
	 */
	private static String subtitle(Block block, BlockContext context)
	{
		Instant start;
		Instant end;
		if (isBingo(block))
		{
			Bingo bingo = context.getBingoView().getBingo();
			start = bingo == null ? null : Times.parse(bingo.getStartsAt());
			end = bingo == null ? null : Times.parse(bingo.getEndsAt());
		}
		else
		{
			Competition competition = context.currentCompetition(block.setting("dates", null));
			start = competition == null ? null : Times.parse(competition.getStartsAt());
			end = competition == null ? null : Times.parse(competition.getEndsAt());
		}
		return start != null && end != null ? Times.range(start, end) : block.setting("subtitle", null);
	}

	private static boolean isBingo(Block block)
	{
		return "bingo".equalsIgnoreCase(block.setting("dates", null));
	}
}

