package com.pvknee.blocks;

import com.pvknee.data.Block;
import com.pvknee.ui.DataTable;
import com.pvknee.ui.Section;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.JComponent;
import lombok.extern.slf4j.Slf4j;

/**
 * A sheet range as a table in a card. The endpoint sends the range's values as the block's rows. Settings:
 * <ul>
 * <li>header: TRUE to use the range's first row as the header, or the header cells separated by commas</li>
 * <li>columns: which columns to show, counting from 1, e.g. 1,3 (default all)</li>
 * <li>widths: each shown column's share of the width, e.g. 2,1 (default equal)</li>
 * </ul>
 */
@Slf4j
class TableBlock implements BlockRenderer
{
	@Override
	public JComponent render(Block block, BlockContext context)
	{
		List<List<String>> rows = block.getRows() == null ? new ArrayList<>() : block.getRows().stream()
			.filter(row -> row != null && row.stream().anyMatch(cell -> cell != null && !cell.trim().isEmpty()))
			.collect(Collectors.toList());

		String headerSetting = block.setting("header", null);
		boolean headerFromRange = "true".equalsIgnoreCase(headerSetting);
		List<String> header = null;
		if (headerFromRange)
		{
			header = rows.isEmpty() ? null : rows.remove(0);
		}
		else if (headerSetting != null && !"false".equalsIgnoreCase(headerSetting))
		{
			header = split(headerSetting);
		}

		if (rows.isEmpty())
		{
			log.debug("No rows for table {}", block.getSettings());
			return null;
		}

		int width = rows.stream().mapToInt(List::size).max().orElse(0);
		int[] columns = columns(block.setting("columns", null), width);
		double[] weights = weights(block.setting("widths", null), columns.length);
		List<List<String>> shown = rows.stream().map(row -> pick(row, columns)).collect(Collectors.toList());
		// A header from the range follows the column choice; one typed in the setting already names the shown columns.
		List<String> shownHeader = headerFromRange && header != null ? pick(header, columns) : header;

		return Section.titled(block.setting("title", null), new DataTable(shownHeader, shown, weights, context.getColours()), context.getColours());
	}

	/**
	 * The 0-based columns to show: the setting's 1-based numbers within the range, or every column.
	 */
	private static int[] columns(String setting, int width)
	{
		int[] picked = setting == null ? new int[0] : split(setting).stream()
			.mapToInt(TableBlock::number)
			.filter(n -> n >= 1 && n <= width)
			.map(n -> n - 1)
			.toArray();
		if (picked.length > 0)
		{
			return picked;
		}

		int[] all = new int[width];
		Arrays.setAll(all, i -> i);
		return all;
	}

	/**
	 * Each column's share of the width from the setting; missing or invalid ones get an equal share.
	 */
	private static double[] weights(String setting, int count)
	{
		List<String> parts = setting == null ? new ArrayList<>() : split(setting);
		double[] weights = new double[count];
		for (int i = 0; i < count; i++)
		{
			int weight = i < parts.size() ? number(parts.get(i)) : 0;
			weights[i] = weight > 0 ? weight : 1;
		}
		return weights;
	}

	private static List<String> pick(List<String> row, int[] columns)
	{
		List<String> cells = new ArrayList<>();
		for (int column : columns)
		{
			cells.add(column < row.size() ? row.get(column) : "");
		}
		return cells;
	}

	private static List<String> split(String setting)
	{
		return Arrays.stream(setting.split(","))
			.map(String::trim)
			.collect(Collectors.toList());
	}

	private static int number(String text)
	{
		try
		{
			return Integer.parseInt(text.trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.pvknee.blocks;

import com.pvknee.data.Block;
import com.pvknee.ui.Fonts;
import com.pvknee.ui.Labels;
import com.pvknee.ui.Pill;
import com.pvknee.ui.ThemeColours;
import java.awt.Color;
import java.awt.FlowLayout;
import java.awt.Font;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

class TextBlock implements BlockRenderer
{
	@Override
	public JComponent render(Block block, BlockContext context)
	{
		String text = block.setting("text", null);
		if (text == null)
		{
			return null;
		}

		String style = block.setting("style", "").toLowerCase();
		boolean signoff = style.contains("signoff");
		boolean muted = signoff || style.contains("muted");
		boolean italic = signoff || style.contains("italic");
		boolean centred = signoff || !"left".equalsIgnoreCase(block.setting("align", "center"));

		Font font = signoff ? FontManager.getRunescapeSmallFont()
			: style.contains("bold") ? FontManager.getRunescapeBoldFont()
			: Fonts.body();
		if (italic)
		{
			font = font.deriveFont(font.getStyle() | Font.ITALIC);
		}

		ThemeColours colours = context.getColours();
		Color colour = muted ? colours.getMuted() : colours.getValue();
		if (style.contains("pill"))
		{
			JPanel row = new JPanel(new FlowLayout(centred ? FlowLayout.CENTER : FlowLayout.LEFT, 0, 0));
			row.setOpaque(false);
			row.add(new Pill(text, colour, context.mutedGlyph(block.setting("icon", null), Pill.ICON_SIZE)));
			return row;
		}
		return Labels.label(text, colour, font, Labels.CONTENT_WIDTH, centred);
	}
}

package com.pvknee.blocks;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Locale;

/**
 * Parses endpoint times and formats them for display, in the member's local time zone or in UTC.
 */
public final class Times
{
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("EEE d MMM uuuu, HH:mm 'UTC'", Locale.ENGLISH)
		.withZone(ZoneOffset.UTC);
	/** An item is ending soon in its final 24 hours. */
	private static final Duration ENDING_SOON = Duration.ofHours(24);
	/** Spans longer than this get one bar segment per week instead of per day. */
	private static final Duration DAILY_SEGMENTS = Duration.ofDays(14);
	/** Longer spans get one plain bar: day or week segments would be too thin to read. */
	private static final Duration MAX_SEGMENTED = Duration.ofDays(60);

	private static volatile boolean utc;

	private Times()
	{
	}

	/**
	 * Shows times in UTC, with a "UTC" suffix, instead of the local time zone.
	 */
	public static void setUtc(boolean utc)
	{
		Times.utc = utc;
	}

	/**
	 * The date and time to the minute, always in UTC whatever the time setting, e.g. "Tue 3 Nov 2026, 21:35 UTC".
	 */
	public static String utcStamp(Instant instant)
	{
		return STAMP.format(instant);
	}

	/**
	 * An ISO-8601 time, or null if it is missing or invalid.
	 */
	public static Instant parse(String iso)
	{
		if (iso == null || iso.isEmpty())
		{
			return null;
		}

		try
		{
			return Instant.parse(iso);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	/**
	 * e.g. "Today, 17:00", "Tomorrow, 17:00" or "Fri 6 Nov, 17:00", or just the day when the time of day is not
	 * known.
	 */
	public static String date(Instant instant, boolean withTime)
	{
		String dayText = day(instant.atZone(zone()).toLocalDate());
		return withTime ? dayText + ", " + time(instant) : dayText;
	}

	/**
	 * A calendar day relative to today in the member's time zone: "Today", "Tomorrow" or e.g. "Sat 7 Nov".
	 */
	public static String day(LocalDate day)
	{
		LocalDate today = LocalDate.now(zone());
		return day.equals(today) ? "Today"
			: day.equals(today.plusDays(1)) ? "Tomorrow"
			: DAY.format(day);
	}

	/**
	 * The calendar day a date-only sheet time stands for. The sheet sends such days as midnight UTC, so the day is
	 * read in UTC whatever the member's time zone.
	 */
	public static LocalDate sheetDay(Instant instant)
	{
		return instant.atZone(ZoneOffset.UTC).toLocalDate();
	}

	/**
	 * When a calendar day starts in the member's time zone (or in UTC when times are shown in UTC).
	 */
	public static Instant startOfDay(LocalDate day)
	{
		return day.atStartOfDay(zone()).toInstant();
	}

	/**
	 * The days from start to end, e.g. "Fri 30 Oct – Fri 6 Nov", always as dates rather than "Today" or "Tomorrow".
	 */
	public static String range(Instant start, Instant end)
	{
		ZoneId zone = zone();
		return DAY.format(start.atZone(zone)) + " – " + DAY.format(end.atZone(zone));
	}

	/**
	 * e.g. "17:05", or "17:05 UTC" when times are shown in UTC.
	 */
	public static String time(Instant instant)
	{
		return TIME.format(instant.atZone(zone())) + (utc ? " UTC" : "");
	}

	/**
	 * How far now is through the span from start to end, between 0 and 1.
	 */
	public static double progress(Instant start, Instant end)
	{
		long total = Duration.between(start, end).toMillis();
		return total <= 0 ? 1 : (double) Duration.between(start, Instant.now()).toMillis() / total;
	}

	/**
	 * The number of bar segments for a span: one per day, one per week when it is over 14 days, and a single plain bar
	 * when it is over 60 days.
	 */
	public static int segments(Instant start, Instant end)
	{
		Duration span = Duration.between(start, end);
		if (span.compareTo(MAX_SEGMENTED) > 0)
		{
			return 1;
		}
		Duration unit = span.compareTo(DAILY_SEGMENTS) > 0 ? Duration.ofDays(7) : Duration.ofDays(1);
		return (int) Math.max(1, (span.toMillis() + unit.toMillis() - 1) / unit.toMillis());
	}

	/**
	 * Whether an item ending at this time is in its final 24 hours.
	 */
	public static boolean endingSoon(Instant end)
	{
		Instant now = Instant.now();
		return now.isBefore(end) && Duration.between(now, end).compareTo(ENDING_SOON) < 0;
	}

	/**
	 * e.g. "5d 20h left", or "Ends in 5h 12m" in the final 24 hours.
	 */
	public static String left(Instant end)
	{
		String duration = duration(Duration.between(Instant.now(), end));
		return endingSoon(end) ? "Ends in " + duration : duration + " left";
	}

	/**
	 * e.g. "6d 4h", "5h 12m" or "12m".
	 */
	public static String duration(Duration duration)
	{
		long minutes = Math.max(0, duration.toMinutes());
		long days = minutes / (24 * 60);
		long hours = minutes / 60 % 24;

		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + minutes % 60 + "m";
		}
		return minutes > 0 ? minutes + "m" : "<1m";
	}

	private static ZoneId zone()
	{
		return utc ? ZoneOffset.UTC : ZoneId.systemDefault();
	}
}

package com.pvknee.chat;

import com.pvknee.DevLog;
import com.pvknee.data.ClanData;
import com.pvknee.data.ClanDataClient;
import com.pvknee.data.Competition;
import com.pvknee.data.Placing;
import com.pvknee.player.PlayerInfo;
import com.pvknee.player.PlayerState;
import com.pvknee.ui.Labels;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.util.Text;

/**
 * !sotw and !botw: when the member types one in chat, a game message only they see with the challenge, its time left
 * and their place and score. Others typing it get no reply from this plugin, and nothing is sent to the game.
 */
@Singleton
public class ChatCommands
{
	private static final String SOTW = "!sotw";
	private static final String BOTW = "!botw";

	private final ChatCommandManager chatCommandManager;
	private final ChatSender chatSender;
	private final ClanDataClient clanData;
	private final PlayerInfo playerInfo;
	private final DevLog devLog;

	@Inject
	ChatCommands(ChatCommandManager chatCommandManager, ChatSender chatSender, ClanDataClient clanData,
		PlayerInfo playerInfo, DevLog devLog)
	{
		this.chatCommandManager = chatCommandManager;
		this.chatSender = chatSender;
		this.clanData = clanData;
		this.playerInfo = playerInfo;
		this.devLog = devLog;
	}

	public void start()
	{
		chatCommandManager.registerCommand(SOTW, (chat, text) -> reply(chat, "skill", "cmd_sotw"));
		chatCommandManager.registerCommand(BOTW, (chat, text) -> reply(chat, "boss", "cmd_botw"));
	}

	public void stop()
	{
		chatCommandManager.unregisterCommand(SOTW);
		chatCommandManager.unregisterCommand(BOTW);
	}

	/**
	 * Runs on the client thread when anyone's chat message starts with the command; only the member's own get a reply.
	 */
	private void reply(ChatMessage chat, String type, String key)
	{
		PlayerState player = playerInfo.get();
		boolean own = chat.getType() == ChatMessageType.PRIVATECHATOUT || player.isNamed(Text.sanitize(chat.getName()));
		if (!own)
		{
			return;
		}

		devLog.log("command: {} typed", key);
		clanData.recent("command", data -> answer(data, player, type, key));
	}

	/**
	 * Fills the template from the standings in the loaded data; null if nothing could be loaded.
	 */
	private void answer(ClanData data, PlayerState player, String type, String key)
	{
		if (data == null)
		{
			devLog.log("command: no clan data");
			send("The clan data couldn't be loaded. Try again in a few minutes.", Map.of());
			return;
		}

		Competition competition = data.getCompetitions() == null ? null : data.getCompetitions().current(type);
		if (competition == null)
		{
			devLog.log("command: no current {} challenge", type);
			send("There's no " + ("boss".equals(type) ? "Boss" : "Skill") + " of the Week right now.", Map.of());
			return;
		}

		Map<String, List<String>> values = Messages.challengeValues(data, type);
		placeAndScore(values, Placing.find(Placing.board(competition), player::isNamed), type);
		send(Messages.template(data, key), values);
	}

	/**
	 * Fills {place}, {gain} and {you} (place and score together, e.g. "2nd, 1,942 xp") from the full standings, so a
	 * place below the table's cut-off still shows.
	 */
	private static void placeAndScore(Map<String, List<String>> values, Placing mine, String type)
	{
		if (mine == null)
		{
			values.put("place", Messages.one("not on the board yet"));
			values.put("gain", Messages.one("no gains yet"));
			values.put("you", Messages.one("skill".equals(type) ? "no xp yet" : "boss".equals(type) ? "no kills yet" : "no gains yet"));
			return;
		}

		String place = Labels.ordinal(mine.getPlace());
		String score = Labels.score(mine.getGained(), type);
		values.put("place", Messages.one(place));
		values.put("gain", Messages.one(score));
		values.put("you", Messages.one(place + ", " + score));
	}

	private void send(String template, Map<String, List<String>> values)
	{
		devLog.log("command: {}", Messages.plain(template, values));
		chatSender.send(template, values);
	}
}

package com.pvknee.chat;

import java.awt.Color;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ChatColorConfig;

/**
 * Sends the plugin's chat messages with values in RuneLite's game message highlight colour (Chat Color settings),
 * the opaque or transparent one for the chatbox at the time. Used directly because RuneLite swaps its default
 * highlight for the game's own game message colour when one is set, which would make values look like the wording.
 * Safe to call from any thread.
 */
@Singleton
class ChatSender
{
	private final Client client;
	private final ClientThread clientThread;
	private final ChatColorConfig chatColors;
	private final ChatMessageManager chatMessageManager;

	@Inject
	ChatSender(Client client, ClientThread clientThread, ChatColorConfig chatColors, ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.chatColors = chatColors;
		this.chatMessageManager = chatMessageManager;
	}

	void send(String template, Map<String, List<String>> values)
	{
		clientThread.invoke(() -> chatMessageManager.queue(Messages.message(template, values, highlight())));
	}

	private Color highlight()
	{
		boolean transparent = client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) != 0;
		return transparent ? chatColors.transparentGameMessageHighlight() : chatColors.opaqueGameMessageHighlight();
	}
}

package com.pvknee.chat;

import com.pvknee.DevLog;
import com.pvknee.PvKneeConfig;
import com.pvknee.data.ClanData;
import com.pvknee.data.ClanDataClient;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/**
 * Once per login, the sheet's "login" message filled with the current challenges, as a game message only the member
 * sees (off by default). Also starts the one quiet endpoint load at login that the bingo team icons and overlay use
 * while the panel is closed.
 */
@Singleton
public class LoginMessage
{
	private final ClanDataClient clanData;
	private final Client client;
	private final ClientThread clientThread;
	private final ChatSender chatSender;
	private final EventBus eventBus;
	private final PvKneeConfig config;
	private final DevLog devLog;

	/** Whether this login has been greeted; hops and reconnects log in again without a new greeting. */
	private boolean greeted;

	@Inject
	LoginMessage(ClanDataClient clanData, Client client, ClientThread clientThread, ChatSender chatSender,
		EventBus eventBus, PvKneeConfig config, DevLog devLog)
	{
		this.clanData = clanData;
		this.client = client;
		this.clientThread = clientThread;
		this.chatSender = chatSender;
		this.eventBus = eventBus;
		this.config = config;
		this.devLog = devLog;
	}

	/**
	 * Starts the message. Already logged in counts as greeted, so turning the plugin on mid-session stays quiet.
	 */
	public void start()
	{
		eventBus.register(this);
		clientThread.invoke(() ->
		{
			greeted = client.getGameState() == GameState.LOGGED_IN;
		});
		if (clanData.latest() == null)
		{
			// The saved copy, so the team icons have data before the first load.
			clanData.loadSaved((data, savedAt) -> {});
		}
	}

	public void stop()
	{
		eventBus.unregister(this);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			greeted = false;
		}
		else if (event.getGameState() == GameState.LOGGED_IN && !greeted)
		{
			greeted = true;
			if (!needsLoginLoad())
			{
				devLog.log("login: nothing needs the clan data, not loading it");
				return;
			}
			// Loaded even with the login message off, so the team icons and overlay have fresh data.
			clanData.recent("login", this::greet);
		}
	}

	/**
	 * Whether any feature that works while the panel is closed is on: the login message or the bingo team icons and
	 * overlay. Otherwise the data loads on first use, e.g. opening the panel.
	 */
	private boolean needsLoginLoad()
	{
		return config.loginMessage() || config.teamIconsInChat() || config.teamIconsAboveHeads()
			|| config.bingoTeamOverlay();
	}

	private void greet(ClanData data)
	{
		if (data == null)
		{
			devLog.log("login: no clan data");
			return;
		}
		if (!config.loginMessage())
		{
			devLog.log("login: message turned off");
			return;
		}

		String template = Messages.template(data, "login");
		Map<String, List<String>> values = Messages.challengeValues(data);
		devLog.log("login: {}", Messages.plain(template, values));
		chatSender.send(template, values);
	}
}

package com.pvknee.chat;

import com.pvknee.blocks.Times;
import com.pvknee.data.ClanData;
import com.pvknee.data.Competition;
import com.pvknee.data.Competitions;
import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.util.Text;

/**
 * Builds chat messages from the sheet's templates, e.g. "{skill} | {timeLeft} left": the wording in RuneLite's normal
 * chat colour and each placeholder's value in the given highlight colour (see {@link ChatSender}). A
 * placeholder can hold several values, each highlighted and joined with ", ". A placeholder
 * without a value, or one the plugin doesn't know, stays as typed.
 */
final class Messages
{
	private static final Pattern PLACEHOLDER = Pattern.compile("\\{(\\w+)}");
	private static final String SEPARATOR = ", ";
	/** The wording used when the sheet has none for a key. */
	private static final Map<String, String> DEFAULTS = Map.of(
		"login", "PvKnee | Skill: {skill} | Boss: {boss} | {timeLeft} left",
		"cmd_sotw", "{skill} | {timeLeft} left | You: {you}",
		"cmd_botw", "{boss} | {timeLeft} left | You: {you}");

	private Messages()
	{
	}

	/**
	 * The sheet's wording for a message, or the built-in default when it is missing or blank.
	 */
	static String template(ClanData data, String key)
	{
		String wording = data.getMessages() == null ? null : data.getMessages().get(key);
		return wording == null || wording.trim().isEmpty() ? DEFAULTS.get(key) : wording.trim();
	}

	/**
	 * The placeholders every message can use: {skill}, {boss} and {timeLeft}, for the current challenges. Missing
	 * ones are left out, so they stay as typed.
	 */
	static Map<String, List<String>> challengeValues(ClanData data)
	{
		return challengeValues(data, "skill");
	}

	/**
	 * The same, with {timeLeft} from this type's challenge (skill or boss), or the other one if it has none.
	 */
	static Map<String, List<String>> challengeValues(ClanData data, String timeFrom)
	{
		Map<String, List<String>> values = new HashMap<>();
		Competitions competitions = data.getCompetitions();
		Competition skill = competitions == null ? null : competitions.current("skill");
		Competition boss = competitions == null ? null : competitions.current("boss");
		if (skill != null && skill.getName() != null)
		{
			values.put("skill", one(skill.getName()));
		}
		if (boss != null && boss.getName() != null)
		{
			values.put("boss", one(boss.getName()));
		}

		Competition timed = "boss".equals(timeFrom) ? (boss != null ? boss : skill) : (skill != null ? skill : boss);
		Instant end = timed == null ? null : Times.parse(timed.getEndsAt());
		if (end != null)
		{
			values.put("timeLeft", one(Times.duration(Duration.between(Instant.now(), end))));
		}
		return values;
	}

	static List<String> one(String value)
	{
		return Collections.singletonList(value);
	}

	/**
	 * The filled template as plain text, e.g. for the dev log.
	 */
	static String plain(String template, Map<String, List<String>> values)
	{
		StringBuilder text = new StringBuilder();
		Matcher matcher = PLACEHOLDER.matcher(template);
		int at = 0;
		while (matcher.find())
		{
			List<String> value = values.get(matcher.group(1));
			text.append(template, at, matcher.start()).append(value == null ? matcher.group() : String.join(SEPARATOR, value));
			at = matcher.end();
		}
		return text.append(template.substring(at)).toString();
	}

	/**
	 * A game message only the member sees: the wording in the normal chat colour, the values in the highlight colour.
	 * All text is escaped, so the sheet cannot add chat formatting.
	 */
	static QueuedMessage message(String template, Map<String, List<String>> values, Color highlight)
	{
		// The game hides everything up to the first "|" of a game message as a prefix, so an empty prefix keeps
		// templates such as "{skill} | {timeLeft} left" whole.
		ChatMessageBuilder builder = new ChatMessageBuilder().append("|").append(ChatColorType.NORMAL);
		Matcher matcher = PLACEHOLDER.matcher(template);
		int at = 0;
		while (matcher.find())
		{
			builder.append(template.substring(at, matcher.start()));
			List<String> value = values.get(matcher.group(1));
			if (value == null)
			{
				builder.append(matcher.group());
			}
			else
			{
				for (int i = 0; i < value.size(); i++)
				{
					builder.append(i == 0 ? "" : SEPARATOR)
						.append(highlight, Text.escapeJagex(value.get(i)))
						.append(ChatColorType.NORMAL);
				}
			}
			at = matcher.end();
		}
		builder.append(template.substring(at));

		return QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(builder.build())
			.build();
	}
}

package com.pvknee.data;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * The clan bingo, worked out by the Apps Script from the active bingo sheet. Null in {@link ClanData} when there is none.
 */
@Data
public class Bingo
{
	private String name;
	private String startsAt;
	private String endsAt;
	/** Null if the endpoint sends a state this version doesn't know. */
	private State state;
	private int boardSize = 5;
	/** Where to post proof, e.g. "#bingo-submissions". */
	private String submit;
	/** Empty until the start, so the board isn't revealed early. */
	private List<Tile> tiles = new ArrayList<>();
	/** Sorted by points, best first. */
	private List<Team> teams = new ArrayList<>();

	public enum State
	{
		@SerializedName("upcoming") UPCOMING,
		@SerializedName("running") RUNNING,
		/** Ended, but the results aren't final yet. */
		@SerializedName("tallying") TALLYING,
		@SerializedName("final") FINAL
	}

	public enum Status
	{
		@SerializedName("progress") PROGRESS,
		@SerializedName("done") DONE
	}

	/**
	 * The team of this name, or null.
	 */
	public Team team(String teamName)
	{
		return teams.stream()
			.filter(team -> team.getName() != null && team.getName().equals(teamName))
			.findFirst()
			.orElse(null);
	}

	/**
	 * The tile with this number, or null.
	 */
	public Tile tile(int num)
	{
		return tiles.stream()
			.filter(tile -> tile.getNum() == num)
			.findFirst()
			.orElse(null);
	}

	@Data
	public static class Tile
	{
		/** The tile's place on the board, counting from 1, left to right and top to bottom. */
		private int num;
		private String name;
		private String description;
		private int itemId;
		private double points;
		/** For a tile with parts, the number of parts. */
		private long needed = 1;
		/** E.g. "pieces", "kills", "xp"; "parts" for a tile with parts. */
		private String unit;
		private List<Part> parts = new ArrayList<>();
	}

	@Data
	public static class Part
	{
		private String name;
		private long needed = 1;
		/** 0 when the part has no icon of its own. */
		private int itemId;
	}

	@Data
	public static class Team
	{
		private String name;
		/** Hex colour; null for a default one (see {@code TeamColours}). */
		private String colour;
		/** Teams on the same points share a rank. */
		private int rank;
		private double points;
		private int tilesDone;
		private List<Member> members = new ArrayList<>();
		/** Only tiles with at least one log row; any other tile is not started. */
		private List<Progress> progress = new ArrayList<>();
	}

	@Data
	public static class Member
	{
		private String name;
		/** Null if the endpoint stops sending member points. */
		private Double points;
		/** Done tiles they contributed to. */
		private int tiles;
	}

	@Data
	public static class Progress
	{
		private int num;
		private Status status;
		/** Capped at the tile's needed; for a tile with parts, the parts complete. */
		private long amount;
		private String completedAt;
		private String completedBy;
		private List<Contributor> contributors = new ArrayList<>();
		/** In the tile's part order; empty for a tile without parts. */
		private List<PartProgress> parts = new ArrayList<>();
	}

	@Data
	public static class PartProgress
	{
		private String name;
		private long needed = 1;
		private long amount;
		private boolean done;
		private List<Contributor> contributors = new ArrayList<>();
	}

	@Data
	public static class Contributor
	{
		private String name;
		private long amount;
		/** What they got, e.g. "Bandos tassets"; may be empty. */
		private String note;
	}
}

package com.pvknee.data;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

@Data
public class Block
{
	private String type;
	private Map<String, String> settings = new HashMap<>();
	/** The values of the block's sheet range, for blocks that show one (e.g. table); null for the others. */
	private List<List<String>> rows;

	/**
	 * A trimmed setting, or the default if it is missing or blank.
	 */
	public String setting(String key, String fallback)
	{
		String value = settings == null ? null : settings.get(key);
		return value == null || value.trim().isEmpty() ? fallback : value.trim();
	}

	/**
	 * A true or false setting, or the default if it is missing or neither.
	 */
	public boolean booleanSetting(String key, boolean fallback)
	{
		String value = setting(key, "");
		return "true".equalsIgnoreCase(value) || (!"false".equalsIgnoreCase(value) && fallback);
	}

	/**
	 * A whole-number setting, or the default if it is missing or not a number.
	 */
	public int intSetting(String key, int fallback)
	{
		try
		{
			return Integer.parseInt(setting(key, ""));
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}
}

