package com.pvknee.player;

import com.pvknee.DevLog;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks, on the client thread, whether the member is logged in, their name, world and clan rank. Readable from any
 * thread; the listener is told on the Swing thread when anything changes.
 */
@Singleton
public class PlayerInfo
{
	/** How long after a hop the last rank is kept while waiting for the clan channel, in ticks (about 15 seconds). */
	private static final int HOP_GRACE_TICKS = 25;

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final DevLog devLog;

	private volatile PlayerState state = PlayerState.LOGGED_OUT;
	/** The name last logged in with, kept after logging out. */
	private volatile String lastName;
	private Runnable listener;
	/** Set while the name or clan rank may still arrive; read again each tick until both are known. */
	private boolean pending;
	/** Ticks left to keep the last rank after a hop, since the game drops the clan channel until the new world sends it. */
	private int hopTicks;

	@Inject
	PlayerInfo(Client client, ClientThread clientThread, EventBus eventBus, DevLog devLog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.devLog = devLog;
	}

	/**
	 * Starts tracking. The listener runs on the Swing thread after each change.
	 */
	public void start(Runnable listener)
	{
		this.listener = listener;
		eventBus.register(this);
		clientThread.invoke(() ->
		{
			pending = client.getGameState() == GameState.LOGGED_IN;
		});
	}

	public void stop()
	{
		eventBus.unregister(this);
		listener = null;
		state = PlayerState.LOGGED_OUT;
	}

	public PlayerState get()
	{
		return state;
	}

	/**
	 * The name the member last logged in with, kept after they log out; null if they haven't logged in yet.
	 */
	public String lastName()
	{
		return lastName;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.HOPPING)
		{
			hopTicks = HOP_GRACE_TICKS;
		}
		else if (gameState == GameState.LOGGED_IN)
		{
			pending = true;
		}
		else if (gameState == GameState.LOGIN_SCREEN)
		{
			pending = false;
			hopTicks = 0;
			update(PlayerState.LOGGED_OUT);
		}
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (event.getClanId() == ClanID.CLAN)
		{
			pending = true;
			if (event.getClanChannel() != null)
			{
				hopTicks = 0;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pending)
		{
			read();
		}
	}

	private void read()
	{
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		if (name == null)
		{
			return;
		}

		ClanChannel channel = client.getClanChannel(ClanID.CLAN);
		if (channel == null && hopTicks > 0 && name.equals(state.getName()))
		{
			// Just hopped and the new world hasn't sent the clan channel yet: keep the last rank meanwhile.
			hopTicks--;
			update(new PlayerState(true, name, client.getWorld(), state.getRank(), state.getRankTitle(), state.getRankTitles()));
			return;
		}
		hopTicks = 0;

		ClanSettings settings = client.getClanSettings(ClanID.CLAN);
		ClanMember member = settings == null ? null : settings.findMember(name);
		ClanRank rank = channel == null || member == null ? null : member.getRank();
		ClanTitle title = rank == null ? null : settings.titleForRank(rank);

		// In a clan channel whose settings haven't arrived yet: try again next tick.
		pending = channel != null && settings == null;
		update(new PlayerState(true, name, client.getWorld(), rank, title == null ? null : title.getName(),
			rank == null ? Collections.emptyMap() : rankTitles(settings)));
	}

	/**
	 * Every rank title the clan uses, in lower case, with the lowest rank that has it.
	 */
	private static Map<String, Integer> rankTitles(ClanSettings settings)
	{
		Map<String, Integer> titles = new HashMap<>();
		for (int rank = ClanRank.GUEST.getRank(); rank <= ClanRank.JMOD.getRank(); rank++)
		{
			ClanTitle title = settings.titleForRank(new ClanRank(rank));
			if (title != null && title.getName() != null)
			{
				titles.putIfAbsent(title.getName().toLowerCase(Locale.ENGLISH), rank);
			}
		}
		return Collections.unmodifiableMap(titles);
	}

	private void update(PlayerState next)
	{
		PlayerState previous = state;
		if (previous.equals(next))
		{
			return;
		}

		state = next;
		if (next.getName() != null)
		{
			lastName = next.getName();
		}
		if (!next.isLoggedIn())
		{
			devLog.log("player: logged out");
		}
		else
		{
			if (!Objects.equals(previous.getName(), next.getName()) || previous.getWorld() != next.getWorld())
			{
				devLog.log("player: {} on world {}", next.getName(), next.getWorld());
			}
			if (!Objects.equals(previous.getRank(), next.getRank()))
			{
				devLog.log("player: clan rank {}", next.getRank() == null ? "none" : next.getRankTitle() + " (" + next.getRank().getRank() + ")");
			}
		}

		Runnable listener = this.listener;
		if (listener != null)
		{
			SwingUtilities.invokeLater(listener);
		}
	}
}

package com.pvknee.player;

import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import lombok.Value;
import net.runelite.api.clan.ClanRank;
import net.runelite.client.util.Text;

/**
 * What the plugin knows about the member in game, at one moment.
 */
@Value
public class PlayerState
{
	public static final PlayerState LOGGED_OUT = new PlayerState(false, null, 0, null, null, Collections.emptyMap());

	boolean loggedIn;
	/** The display name; null until the game has it. */
	String name;
	int world;
	/** The clan rank; null when not in the clan or not known yet. */
	ClanRank rank;
	/** The rank's title as the clan names it, e.g. "Administrator"; null with no rank. */
	String rankTitle;
	/** The clan's rank titles in lower case, each with the lowest rank that has it; empty when not in the clan. */
	Map<String, Integer> rankTitles;

	/**
	 * Whether this is the member's name, e.g. as Wise Old Man spells it. Ignores case and treats spaces, underscores
	 * and hyphens as the same.
	 */
	public boolean isNamed(String other)
	{
		return name != null && other != null && nameKey(name).equals(nameKey(other));
	}

	/**
	 * Whether the member's clan rank is at least this one: a rank number, or a title as the clan names it, e.g.
	 * "Administrator". Blank needs no rank; otherwise logged out, not in the clan or an unknown title is never enough.
	 */
	public boolean hasRank(String required)
	{
		if (required == null || required.trim().isEmpty())
		{
			return true;
		}
		if (rank == null)
		{
			return false;
		}

		Integer needed;
		try
		{
			needed = Integer.parseInt(required.trim());
		}
		catch (NumberFormatException e)
		{
			needed = rankTitles.get(required.trim().toLowerCase(Locale.ENGLISH));
		}
		return needed != null && rank.getRank() >= needed;
	}

	/**
	 * The name as {@link #isNamed} compares it, for looking names up in a map: RuneLite's own Jagex name form, in
	 * lower case without tags.
	 */
	public static String nameKey(String name)
	{
		return Text.toJagexName(Text.standardize(name));
	}
}

package com.pvknee.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded panel, slightly lighter than the page, with a subtle border.
 */
public class Card extends JPanel
{
	/** Also the background of other kit pieces, e.g. {@link PagePicker}. */
	static final Color BACKGROUND = new Color(48, 48, 48);
	/** Also the hover tint of other kit pieces, e.g. {@link PagePicker}. */
	static final Color HOVER = new Color(58, 58, 58);
	/** Also the outline of other kit pieces, e.g. {@link Pill}. */
	static final Color BORDER = new Color(64, 64, 64);

	private static final float[] DASH = {4, 3};

	private final boolean bordered;
	private boolean hovered;
	private Color outline = BORDER;
	private int arc = Spacing.ARC;
	private boolean dashed;

	public Card(LayoutManager layout)
	{
		this(layout, true);
	}

	/**
	 * A card without the border, for clickable areas inside another card.
	 */
	public Card(LayoutManager layout, boolean bordered)
	{
		super(layout);
		this.bordered = bordered;
		setOpaque(false);
		setBackground(BACKGROUND);
		setBorder(new EmptyBorder(Spacing.PADDING, Spacing.PADDING, Spacing.PADDING, Spacing.PADDING));
	}

	/**
	 * Draws the border in this colour instead of the default, e.g. the accent to mark the active choice.
	 * Null restores the default.
	 */
	public void setOutline(Color colour)
	{
		outline = colour == null ? BORDER : colour;
		repaint();
	}

	/**
	 * Rounds the corners by this arc diameter instead of the card default, e.g. {@link Spacing#CONTROL_ARC}.
	 */
	public void setArc(int arc)
	{
		this.arc = arc;
		repaint();
	}

	/**
	 * Draws the border dashed, e.g. for a hint standing in for content that isn't there yet.
	 */
	public void setDashed(boolean dashed)
	{
		this.dashed = dashed;
		repaint();
	}

	/**
	 * Makes the whole card clickable, with a hand cursor and a hover highlight.
	 * Acts when the left button is released over the card, even if the mouse moved while pressed.
	 * A disabled card ignores clicks and hover.
	 */
	public void onClick(Runnable action)
	{
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (isEnabled() && SwingUtilities.isLeftMouseButton(e) && contains(e.getPoint()))
				{
					action.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (isEnabled())
				{
					setHovered(true);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHovered(false);
			}
		});
	}

	@Override
	public void setEnabled(boolean enabled)
	{
		super.setEnabled(enabled);
		if (!enabled)
		{
			setHovered(false);
		}
	}

	/**
	 * Whether the mouse is over a clickable card, for kit pieces that paint themselves.
	 */
	protected boolean isHovered()
	{
		return hovered;
	}

	private void setHovered(boolean hovered)
	{
		this.hovered = hovered;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(hovered ? HOVER : getBackground());
		g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		if (bordered)
		{
			g2.setColor(outline);
			if (dashed)
			{
				g2.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 10, DASH, 0));
			}
			g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		}
		g2.dispose();
	}
}

