package com.pvknee.ui;

import java.awt.Color;
import java.awt.Font;
import java.util.Objects;
import java.util.function.Supplier;
import javax.swing.JLabel;
import javax.swing.SwingConstants;

/**
 * A wrapped label whose text comes from a supplier, so it can be updated in place (e.g. "Ends in 6d 4h").
 * A null text hides the label.
 */
public class LiveLabel extends JLabel
{
	private final Supplier<String> text;
	private final int width;
	private final boolean centred;
	private String shown;

	public LiveLabel(Supplier<String> text, Color colour, Font font, int width, boolean centred)
	{
		this.text = text;
		this.width = width;
		this.centred = centred;
		setForeground(colour);
		setFont(font);
		setHorizontalAlignment(centred ? SwingConstants.CENTER : SwingConstants.LEFT);
		apply(text.get());
	}

	/**
	 * Asks the supplier again and redraws only if the text changed.
	 */
	public void update()
	{
		String next = text.get();
		if (!Objects.equals(next, shown))
		{
			apply(next);
			revalidate();
		}
	}

	private void apply(String next)
	{
		shown = next;
		setVisible(next != null);
		if (next != null)
		{
			Labels.setText(this, next, width, centred);
		}
	}
}

package com.pvknee.ui;

import java.awt.Color;
import javax.swing.JLabel;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * A small card of status lines, e.g. a load error or when the data is from. Hidden while every line is empty.
 */
public class Notice extends Card
{
	private static final int TEXT_WIDTH = Labels.CONTENT_WIDTH - 2 * Spacing.PADDING;

	public Notice()
	{
		super(new DynamicGridLayout(0, 1, 0, Spacing.ITEM_GAP));
		setVisible(false);
	}

	/**
	 * Adds an empty line; lines keep the order they were added in.
	 */
	public Line addLine()
	{
		Line line = new Line();
		add(line);
		return line;
	}

	private void updateVisibility()
	{
		boolean any = false;
		for (int i = 0; i < getComponentCount(); i++)
		{
			any |= getComponent(i).isVisible();
		}
		setVisible(any);
		revalidate();
		repaint();
	}

	public class Line extends JLabel
	{
		private Line()
		{
			setFont(FontManager.getRunescapeSmallFont());
			setVisible(false);
		}

		public void setMessage(String text, Color colour)
		{
			setForeground(colour);
			Labels.setText(this, text, TEXT_WIDTH, false);
			setVisible(true);
			updateVisibility();
		}

		public void clear()
		{
			setVisible(false);
			updateVisibility();
		}
	}
}

