package com.pvknee.ui;

import com.pvknee.data.Page;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;

/**
 * A card-style page dropdown, the same height as {@link IconButton}: the page title with a muted chevron, opening a
 * list of the pages with the current one marked in the accent colour.
 */
public class PagePicker extends Card
{
	private static final int CHEVRON_SIZE = 12;
	private static final int ROW_PADDING_Y = 6;
	private static final Color TITLE = ThemeColours.TEXT;

	private final Consumer<Page> onSelect;
	private final JLabel title = new JLabel();
	private final JLabel chevron = new JLabel();
	private final JPopupMenu menu = new JPopupMenu();
	private List<Page> pages = Collections.emptyList();
	private Page selected;
	private ThemeColours colours = ThemeColours.from(null);

	public PagePicker(Consumer<Page> onSelect)
	{
		super(new BorderLayout(Spacing.ITEM_GAP, 0));
		this.onSelect = onSelect;
		setArc(Spacing.CONTROL_ARC);
		setBorder(new EmptyBorder(0, Spacing.PADDING, 0, Spacing.PADDING));
		setPreferredSize(new Dimension(0, IconButton.SIZE));
		getAccessibleContext().setAccessibleName("Page");

		Labels.noHtml(title);
		title.setForeground(TITLE);
		title.setFont(FontManager.getRunescapeFont());
		add(title, BorderLayout.CENTER);
		add(chevron, BorderLayout.EAST);
		updateChevron();

		menu.setBorder(new LineBorder(BORDER));
		menu.setBackground(BACKGROUND);
		onClick(this::openMenu);
	}

	/**
	 * Replaces the pages and shows the selected one, without telling the listener.
	 */
	public void setPages(List<Page> pages, Page selected, ThemeColours colours)
	{
		this.pages = pages;
		this.colours = colours;
		updateChevron();
		show(selected);
	}

	public List<Page> getPages()
	{
		return pages;
	}

	public Page getSelected()
	{
		return selected;
	}

	/**
	 * Shows the page and tells the listener, as if the member picked it.
	 */
	public void select(Page page)
	{
		show(page);
		onSelect.accept(page);
	}

	private void show(Page page)
	{
		selected = page;
		title.setText(page == null ? "" : page.getTitle());
		Labels.tooltip(this, page == null ? null : page.getTitle());
	}

	private void updateChevron()
	{
		chevron.setIcon(new GlyphIcon(Glyphs.CHEVRON, colours.getMuted(), CHEVRON_SIZE));
	}

	private void openMenu()
	{
		if (pages.isEmpty())
		{
			return;
		}

		menu.removeAll();
		for (Page page : pages)
		{
			menu.add(row(page));
		}
		menu.show(this, 0, getHeight() + Spacing.ITEM_GAP);
	}

	private JPanel row(Page page)
	{
		JLabel label = Labels.plain(page.getTitle(), page == selected ? colours.getAccent() : colours.getValue(),
			FontManager.getRunescapeFont());

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(BACKGROUND);
		row.setBorder(new EmptyBorder(ROW_PADDING_Y, Spacing.PADDING, ROW_PADDING_Y, Spacing.PADDING));
		row.setPreferredSize(new Dimension(getWidth() - 2, label.getPreferredSize().height + 2 * ROW_PADDING_Y));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.add(label, BorderLayout.CENTER);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(BACKGROUND);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && row.contains(e.getPoint()))
				{
					menu.setVisible(false);
					select(page);
				}
			}
		});
		return row;
	}
}

package com.pvknee.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/**
 * A short piece of text in a small rounded outline, optionally after an icon, e.g. "Home world 509". Clickable like
 * a card through {@link #onClick}, filling with the hover tint under the mouse.
 */
public class Pill extends Card
{
	/** The size of the glyph before the text. */
	public static final int ICON_SIZE = 13;
	private static final int PADDING_X = 9;
	private static final int PADDING_Y = 3;
	private static final int ICON_GAP = 5;

	private final JLabel label;

	public Pill(String text, Color colour, Icon icon)
	{
		super(new BorderLayout());
		setBorder(new EmptyBorder(PADDING_Y, PADDING_X, PADDING_Y, PADDING_X));

		label = Labels.plain(text, colour, Fonts.body());
		label.setIcon(icon);
		label.setIconTextGap(ICON_GAP);
		add(label, BorderLayout.CENTER);
	}

	/**
	 * Makes the text bold, e.g. for points.
	 */
	public Pill bold()
	{
		label.setFont(FontManager.getRunescapeBoldFont());
		return this;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (isHovered())
		{
			g2.setColor(HOVER);
			g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, getHeight() - 1, getHeight() - 1);
		}
		g2.setColor(BORDER);
		g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, getHeight() - 1, getHeight() - 1);
		g2.dispose();
	}
}

package com.pvknee.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A place as a word in a small rounded pill, e.g. "1st", in dark text on its place colour: gold, silver and bronze
 * for the top three, grey below.
 */
public class PlacePill extends JComponent
{
	static final int HEIGHT = 18;
	private static final int PADDING = 7;

	private final String text;
	private final Color colour;

	public PlacePill(int rank)
	{
		this.text = Labels.ordinal(rank);
		this.colour = RankBadge.placeColour(rank);
		setFont(FontManager.getRunescapeSmallFont());
		setPreferredSize(new Dimension(getFontMetrics(getFont()).stringWidth(text) + 2 * PADDING, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		int width = getPreferredSize().width;
		int x = (getWidth() - width) / 2;
		int y = (getHeight() - HEIGHT) / 2;
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(colour);
		g2.fillRoundRect(x, y, width, HEIGHT, HEIGHT, HEIGHT);

		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		g2.setFont(getFont());
		g2.setColor(ColorScheme.DARK_GRAY_COLOR);
		int textX = x + (width - g2.getFontMetrics().stringWidth(text)) / 2;
		int textY = y + (HEIGHT + g2.getFontMetrics().getAscent() - g2.getFontMetrics().getDescent()) / 2;
		g2.drawString(text, textX, textY);
		g2.dispose();
	}
}

package com.pvknee.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * A thin rounded bar filled from the left, e.g. a team's tiles done.
 */
public class ProgressBar extends JComponent
{
	private static final int HEIGHT = 5;

	private final double fraction;
	private final Color colour;

	/**
	 * @param fraction how full the bar is, between 0 and 1
	 */
	public ProgressBar(double fraction, Color colour)
	{
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.colour = colour;
		setPreferredSize(new Dimension(0, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int y = (getHeight() - HEIGHT) / 2;
		g2.setColor(Card.BORDER);
		g2.fillRoundRect(0, y, getWidth(), HEIGHT, HEIGHT, HEIGHT);

		// Anything started shows at least a dot, so a little progress isn't lost.
		int filled = fraction == 0 ? 0 : Math.max(HEIGHT, (int) Math.round(getWidth() * fraction));
		if (filled > 0)
		{
			g2.setColor(colour);
			g2.fillRoundRect(0, y, filled, HEIGHT, HEIGHT, HEIGHT);
		}
		g2.dispose();
	}
}

package com.pvknee.ui;

import java.awt.Color;
import java.awt.Dimension;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * A place in the standings: a {@link PlacePill} for the medal places, otherwise the muted place as a word (e.g.
 * "12th"), both centred in a slot of the same width so names line up. Also the medal and place colours.
 */
public final class RankBadge
{
	private static final Color[] MEDALS = {
		new Color(0xFFD700),
		new Color(0xC0C0C0),
		new Color(0xCD7F32),
	};
	/** The place colour below the medals. */
	private static final Color PLACE_GREY = new Color(0x9E9E9E);
	/** The widest plain place the slot is sized for. */
	private static final String WIDEST_PLAIN = "20th";

	private RankBadge()
	{
	}

	/**
	 * The number of places that can get a medal.
	 */
	public static int medalPlaces()
	{
		return MEDALS.length;
	}

	/**
	 * The medal colour of one of the top {@link #medalPlaces()} places.
	 */
	public static Color medalColour(int rank)
	{
		return MEDALS[rank - 1];
	}

	/**
	 * A place's colour: its medal colour for the top {@link #medalPlaces()} places, otherwise a neutral grey.
	 */
	public static Color placeColour(int rank)
	{
		return rank >= 1 && rank <= MEDALS.length ? medalColour(rank) : PLACE_GREY;
	}

	/**
	 * A place pill, which must be for one of the top {@link #medalPlaces()} places, or the plain muted place.
	 */
	public static JComponent of(int rank, boolean medal, ThemeColours colours)
	{
		JComponent place = medal ? new PlacePill(rank) : plain(Labels.ordinal(rank), colours);
		Centred slot = new Centred(place);
		slot.setPreferredSize(new Dimension(slotWidth(colours), Math.max(PlacePill.HEIGHT, place.getPreferredSize().height)));
		return slot;
	}

	/**
	 * Wide enough for any medal pill and for plain places up to "20th".
	 */
	private static int slotWidth(ThemeColours colours)
	{
		int width = plain(WIDEST_PLAIN, colours).getPreferredSize().width;
		for (int rank = 1; rank <= MEDALS.length; rank++)
		{
			width = Math.max(width, new PlacePill(rank).getPreferredSize().width);
		}
		return width;
	}

	private static JLabel plain(String text, ThemeColours colours)
	{
		return Labels.plain(text, colours.getMuted(), FontManager.getRunescapeSmallFont(), SwingConstants.CENTER);
	}
}

package com.pvknee.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import lombok.Builder;
import lombok.Value;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * A ranked table in one card. Medal rows (the top three) get a medal-coloured number badge and name and are slightly
 * taller; a thin divider separates them from the plain rows below. Values are right-aligned in the value colour,
 * optionally after a muted caption such as "3 tiles". A highlighted row, e.g. the member's own, gets a subtle rounded
 * background, and a row can be outlined, e.g. the one being viewed. Rows can also be unranked, e.g. a team's members.
 */
public class RankTable extends Card
{
	static final Color NAME = ThemeColours.TEXT;
	private static final int MEDAL_ROW_PADDING = 7;
	private static final int PLAIN_ROW_PADDING = 5;
	/** Values after a caption get at least this width, so the captions line up. */
	private static final int CAPTIONED_VALUE_WIDTH = 36;

	private final ThemeColours colours;
	private boolean lastWasMedal;

	/**
	 * One row. Only the name is needed.
	 */
	@Value
	@Builder
	public static class Row
	{
		/** The place, shown as a badge; 0 for an unranked row. */
		int rank;
		/** Whether the place gets a medal; it must be one of the top {@link RankBadge#medalPlaces()}. */
		boolean medal;
		String name;
		/** Muted small text right after the name, e.g. "(you)". */
		String suffix;
		/** Muted small text before the value, e.g. "3 tiles". */
		String caption;
		String value;
		boolean highlight;
		/** Outlines the row in this colour, e.g. the accent for the one being viewed; null for none. */
		Color outline;
		/** Makes the row clickable. */
		Runnable onClick;
	}

	public RankTable(ThemeColours colours)
	{
		super(new DynamicGridLayout(0, 1, 0, 0));
		// Rows add the rest of the side padding themselves, so a highlighted row's background reaches past its text.
		setBorder(new EmptyBorder(Spacing.ITEM_GAP, Spacing.PADDING - Spacing.ITEM_GAP, Spacing.ITEM_GAP, Spacing.PADDING - Spacing.ITEM_GAP));
		this.colours = colours;
	}

	/**
	 * Adds the next ranked row. A medal row must be one of the top {@link RankBadge#medalPlaces()} places.
	 */
	public void addRow(int rank, String name, String value, boolean medal, boolean highlight)
	{
		addRow(Row.builder().rank(rank).name(name).value(value).medal(medal).highlight(highlight).build());
	}

	public void addRow(Row row)
	{
		boolean medal = row.isMedal();
		if (lastWasMedal && !medal)
		{
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.setBorder(new EmptyBorder(0, Spacing.ITEM_GAP, 0, Spacing.ITEM_GAP));
			line.add(new Divider(colours.getMuted()));
			add(line);
		}
		lastWasMedal = medal;

		Card panel = new Card(new BorderLayout(2 * Spacing.ITEM_GAP, 0), row.getOutline() != null);
		panel.setArc(Spacing.CONTROL_ARC);
		panel.setOutline(row.getOutline());
		if (row.isHighlight())
		{
			panel.setBackground(HOVER);
		}
		if (row.getOnClick() != null)
		{
			panel.onClick(row.getOnClick());
		}
		int padding = medal ? MEDAL_ROW_PADDING : PLAIN_ROW_PADDING;
		panel.setBorder(new EmptyBorder(padding, Spacing.ITEM_GAP, padding, Spacing.ITEM_GAP));

		if (row.getRank() > 0)
		{
			panel.add(RankBadge.of(row.getRank(), medal, colours), BorderLayout.WEST);
		}
		panel.add(name(row), BorderLayout.CENTER);

		JPanel end = new JPanel(new BorderLayout(2 * Spacing.ITEM_GAP, 0));
		end.setOpaque(false);
		if (row.getCaption() != null)
		{
			end.add(Labels.plain(row.getCaption(), colours.getMuted(), FontManager.getRunescapeSmallFont(), SwingConstants.RIGHT), BorderLayout.CENTER);
		}
		if (row.getValue() != null)
		{
			JLabel value = Labels.plain(row.getValue(), colours.getValue(), Fonts.name(), SwingConstants.RIGHT);
			if (row.getCaption() != null)
			{
				Dimension size = value.getPreferredSize();
				value.setPreferredSize(new Dimension(Math.max(size.width, CAPTIONED_VALUE_WIDTH), size.height));
			}
			end.add(value, BorderLayout.EAST);
		}
		panel.add(end, BorderLayout.EAST);
		add(panel);
	}

	/**
	 * The name, cut short with "..." when it doesn't fit, with its suffix right after it.
	 */
	private JPanel name(Row row)
	{
		JLabel name = Labels.plain(row.getName(), row.isMedal() ? RankBadge.medalColour(row.getRank()) : NAME, Fonts.name(), SwingConstants.LEFT);
		name.setMinimumSize(new Dimension(0, name.getPreferredSize().height));
		name.setMaximumSize(name.getPreferredSize());

		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.X_AXIS));
		panel.setOpaque(false);
		panel.add(name);
		if (row.getSuffix() != null)
		{
			panel.add(Box.createHorizontalStrut(Spacing.ITEM_GAP));
			panel.add(Labels.plain(row.getSuffix(), colours.getMuted(), FontManager.getRunescapeSmallFont(), SwingConstants.LEFT));
		}
		panel.add(Box.createHorizontalGlue());
		return panel;
	}
}

