/**
 * A square grid of clickable tiles, e.g. a bingo board, each with an icon and coloured by status: done tiles are
 * tinted green with a tick in the corner, tiles in progress are tinted orange with a progress line along the bottom,
 * and the rest are plain with the icon slightly dimmed. The selected tile has an outline. Places without a tile are
 * dashed outlines, e.g. for a board that isn't revealed yet.
 */
public class TileGrid extends JComponent
{
	private static final int GAP = 4;
	/** Room around the grid for the outline and ticks, which reach past the tiles' edges. */
	private static final int MARGIN = 3;
	private static final int ARC = 10;
	private static final int OUTLINE_ARC = 14;
	private static final int TICK_SIZE = 10;
	private static final double ICON_SHARE = 0.75;
	private static final Color PLAIN = new Color(42, 42, 42);
	private static final Color DONE_TINT = new Color(76, 175, 80, 56);
	private static final Color PROGRESS_TINT = new Color(255, 152, 0, 41);
	private static final Color LINE_TRACK = new Color(0, 0, 0, 90);
	private static final Color LEGEND_PLAIN = new Color(90, 90, 90);
	private static final Color EMPTY = new Color(74, 74, 74);
	private static final float[] DASH = {4, 3};
	private static final float DIMMED = 0.75f;

	public enum Status
	{
		DONE,
		PROGRESS,
		NOT_STARTED
	}

	@Value
	public static class Tile
	{
		Status status;
		/** How far a tile in progress is, between 0 and 1. */
		double progress;
		String tooltip;
	}

	private final int columns;
	/** The narrowest the grid is laid out; the tiles grow to fill any extra width, and the height follows. */
	private final int width;
	/** The width a grid was last laid out at, so a new one starts at the right height instead of jumping to it. */
	private static int lastWidth;
	/** One per place on the grid, left to right and top to bottom; null for an empty place. */
	private List<Tile> tiles;
	private final Image[] icons;
	private int selected;
	private final Color outline;

	/**
	 * @param selected the selected tile's index, or -1
	 * @param onClick told the index of a tile when it is clicked
	 */
	public TileGrid(int columns, List<Tile> tiles, int selected, Color outline, int width, IntConsumer onClick)
	{
		this.columns = Math.max(1, columns);
		this.width = width;
		this.tiles = tiles;
		this.icons = new Image[tiles.size()];
		this.selected = selected;
		this.outline = outline;
		// Registers with the tooltip manager; the text comes from the tile under the mouse.
		setToolTipText("");

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				int index = tileAt(e.getX(), e.getY());
				if (SwingUtilities.isLeftMouseButton(e) && index >= 0)
				{
					onClick.accept(index);
				}
			}
		});
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				lastWidth = getWidth();
				// The tiles follow the width, so a new width needs a new height.
				if (getHeight() != getPreferredSize().height)
				{
					revalidate();
				}
			}
		});
		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setCursor(Cursor.getPredefinedCursor(tileAt(e.getX(), e.getY()) >= 0 ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
			}
		});
	}

	@Override
	public Dimension getPreferredSize()
	{
		int rows = (tiles.size() + columns - 1) / columns;
		double size = tileSize(layoutWidth(), columns);
		return new Dimension(width, (int) Math.round(2 * MARGIN + rows * size + (rows - 1) * GAP));
	}

	/**
	 * The icon size that suits a grid of this narrowest width and number of columns.
	 */
	public static int iconSize(int width, int columns)
	{
		return (int) Math.round(tileSize(width, Math.max(1, columns)) * ICON_SHARE);
	}

	/**
	 * Changes the tiles' looks and the selection in place, e.g. for another team's board. The number of tiles stays
	 * the same, and so do their icons.
	 */
	public void setTiles(List<Tile> tiles, int selected)
	{
		this.tiles = tiles;
		this.selected = selected;
		repaint();
	}

	/**
	 * Shows a tile's icon, e.g. once it has loaded. It should be {@link #iconSize} big.
	 */
	public void setIcon(int index, Image icon)
	{
		icons[index] = icon;
		repaint();
	}

	/**
	 * A centred key to the tile colours: done, in progress and not started.
	 */
	public static JComponent legend(Color muted)
	{
		JPanel legend = new JPanel(new GridBagLayout());
		legend.setOpaque(false);
		GridBagConstraints constraints = new GridBagConstraints();
		legend.add(legendItem(ThemeColours.DONE, true, "Done", muted), constraints);
		constraints.insets = new Insets(0, 2 * GAP, 0, 0);
		legend.add(legendItem(ThemeColours.IN_PROGRESS, true, "In progress", muted), constraints);
		legend.add(legendItem(LEGEND_PLAIN, false, "Not started", muted), constraints);
		return legend;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int index = tileAt(e.getX(), e.getY());
		return index < 0 ? null : Labels.tooltipText(tiles.get(index).getTooltip());
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < tiles.size(); i++)
		{
			Tile tile = tiles.get(i);
			Rectangle r = bounds(i);
			if (tile == null)
			{
				Graphics2D dashed = (Graphics2D) g2.create();
				dashed.setColor(EMPTY);
				dashed.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 10, DASH, 0));
				dashed.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, ARC, ARC);
				dashed.dispose();
				continue;
			}

			Status status = tile.getStatus();
			g2.setColor(status == Status.DONE ? DONE_TINT : status == Status.PROGRESS ? PROGRESS_TINT : PLAIN);
			g2.fillRoundRect(r.x, r.y, r.width, r.height, ARC, ARC);
			g2.setColor(status == Status.DONE ? ThemeColours.DONE : status == Status.PROGRESS ? ThemeColours.IN_PROGRESS : Card.BORDER);
			g2.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, ARC, ARC);

			paintIcon(g2, icons[i], r, status == Status.NOT_STARTED);
			if (status == Status.PROGRESS)
			{
				paintProgressLine(g2, r, tile.getProgress());
			}
		}

		// Drawn last, as they reach over the neighbouring tiles' gaps.
		for (int i = 0; i < tiles.size(); i++)
		{
			Tile tile = tiles.get(i);
			Rectangle r = bounds(i);
			if (tile != null && tile.getStatus() == Status.DONE)
			{
				new CheckMark(true, TICK_SIZE).paintIcon(this, g2, r.x + r.width - TICK_SIZE + MARGIN, r.y - MARGIN);
			}
			if (i == selected && tile != null)
			{
				g2.setColor(outline);
				g2.setStroke(new BasicStroke(2));
				g2.drawRoundRect(r.x - 2, r.y - 2, r.width + 3, r.height + 3, OUTLINE_ARC, OUTLINE_ARC);
			}
		}
		g2.dispose();
	}

	private static void paintIcon(Graphics2D g2, Image icon, Rectangle r, boolean dimmed)
	{
		if (icon == null)
		{
			return;
		}

		Graphics2D ig = (Graphics2D) g2.create();
		if (dimmed)
		{
			ig.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, DIMMED));
		}
		ig.drawImage(icon, r.x + (r.width - icon.getWidth(null)) / 2, r.y + (r.height - icon.getHeight(null)) / 2, null);
		ig.dispose();
	}

	private static void paintProgressLine(Graphics2D g2, Rectangle r, double progress)
	{
		int x = r.x + 3;
		int width = r.width - 6;
		int y = r.y + r.height - 4;
		g2.setColor(LINE_TRACK);
		g2.fillRect(x, y, width, 2);
		g2.setColor(ThemeColours.IN_PROGRESS);
		g2.fillRect(x, y, Math.max(2, (int) Math.round(width * Math.max(0, Math.min(1, progress)))), 2);
	}

	private static double tileSize(int width, int columns)
	{
		return (width - 2.0 * MARGIN - (columns - 1) * GAP) / columns;
	}

	private int layoutWidth()
	{
		return Math.max(width, getWidth() > 0 ? getWidth() : lastWidth);
	}

	private Rectangle bounds(int index)
	{
		double size = tileSize(layoutWidth(), columns);
		int column = index % columns;
		int row = index / columns;
		int x = (int) Math.round(MARGIN + column * (size + GAP));
		int y = (int) Math.round(MARGIN + row * (size + GAP));
		int right = (int) Math.round(MARGIN + column * (size + GAP) + size);
		int bottom = (int) Math.round(MARGIN + row * (size + GAP) + size);
		return new Rectangle(x, y, right - x, bottom - y);
	}

	/**
	 * The index of the tile at a point, or -1 for a gap or an empty place.
	 */
	private int tileAt(int x, int y)
	{
		for (int i = 0; i < tiles.size(); i++)
		{
			if (tiles.get(i) != null && bounds(i).contains(x, y))
			{
				return i;
			}
		}
		return -1;
	}

	private static JComponent legendItem(Color colour, boolean filled, String text, Color muted)
	{
		JLabel label = Labels.plain(text, muted, FontManager.getRunescapeSmallFont());
		label.setIcon(new SwatchIcon(colour, filled));
		label.setIconTextGap(GAP);
		return label;
	}

	/**
	 * A small square of a tile colour for the legend, filled or just outlined.
	 */
	@Value
	private static class SwatchIcon implements Icon
	{
		private static final int SIZE = 8;

		Color colour;
		boolean filled;

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(colour);
			if (filled)
			{
				g2.fillRoundRect(x, y, SIZE, SIZE, 4, 4);
			}
			else
			{
				g2.drawRoundRect(x, y, SIZE - 1, SIZE - 1, 4, 4);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}
}

package com.pvknee.ui;

import java.awt.BorderLayout;
import java.util.Objects;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * A {@link DayBar} with muted captions under it: the time left on the right, e.g. "5d 22h left", and optionally a
 * fixed caption such as the end date on the left. The time left turns bold in the ending-soon colour in the final
 * 24 hours. Any part can be left out: without a day bar there is no bar.
 */
public class TimeBar extends JPanel
{
	private final DayBar bar;
	private final Supplier<String> right;
	private final BooleanSupplier endingSoon;
	private final ThemeColours colours;
	private final JLabel rightLabel;
	private boolean shownSoon;

	public TimeBar(DayBar bar, String left, Supplier<String> right, BooleanSupplier endingSoon, ThemeColours colours)
	{
		super(new BorderLayout(0, Spacing.ITEM_GAP));
		setOpaque(false);
		this.bar = bar;
		this.right = right;
		this.endingSoon = endingSoon == null ? () -> false : endingSoon;
		this.colours = colours;

		if (bar != null)
		{
			add(bar, BorderLayout.NORTH);
		}

		rightLabel = right == null ? null : caption(null, SwingConstants.RIGHT, colours);
		if (left != null || rightLabel != null)
		{
			JPanel captions = new JPanel(new BorderLayout(Spacing.ITEM_GAP, 0));
			captions.setOpaque(false);
			if (left != null)
			{
				captions.add(caption(left, SwingConstants.LEFT, colours), BorderLayout.WEST);
			}
			if (rightLabel != null)
			{
				captions.add(rightLabel, BorderLayout.CENTER);
			}
			add(captions, BorderLayout.CENTER);
		}
		update();
	}

	/**
	 * Moves the bar and asks for the right caption again, e.g. every minute.
	 */
	public void update()
	{
		if (bar != null)
		{
			bar.update();
		}
		if (rightLabel != null)
		{
			String next = Objects.toString(right.get(), "");
			boolean soon = endingSoon.getAsBoolean();
			if (!next.equals(rightLabel.getText()) || soon != shownSoon)
			{
				shownSoon = soon;
				rightLabel.setText(next);
				Labels.styleTime(rightLabel, soon, colours);
				revalidate();
			}
		}
	}

	private static JLabel caption(String text, int alignment, ThemeColours colours)
	{
		return Labels.plain(Objects.toString(text, ""), colours.getMuted(), FontManager.getRunescapeSmallFont(), alignment);
	}
}

package com.pvknee.ui;

import com.pvknee.data.Page;
import java.awt.BorderLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * The controls above every page: the home button, the page picker and the refresh button with its spinner.
 */
public class TopBar extends JPanel
{
	private final PagePicker pagePicker;
	private final IconButton homeButton = new IconButton(Glyphs.HOME, "Home", this::openHome);
	private final IconButton refreshButton;
	private ThemeColours colours = ThemeColours.from(null);

	public TopBar(Consumer<Page> onSelect, Runnable onRefresh)
	{
		super(new BorderLayout(Spacing.ITEM_GAP, 0));
		pagePicker = new PagePicker(onSelect);
		refreshButton = new IconButton(Glyphs.REFRESH, "Refresh", onRefresh);
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(homeButton, BorderLayout.WEST);
		add(pagePicker, BorderLayout.CENTER);
		add(refreshButton, BorderLayout.EAST);
	}

	/**
	 * Replaces the pages and shows the selected one, without telling the listener.
	 */
	public void setPages(List<Page> pages, Page selected, ThemeColours colours)
	{
		this.colours = colours;
		pagePicker.setPages(pages, selected, colours);
	}

	public List<Page> getPages()
	{
		return pagePicker.getPages();
	}

	public Page getSelected()
	{
		return pagePicker.getSelected();
	}

	/**
	 * Shows the page and tells the listener, as if the member picked it.
	 */
	public void select(Page page)
	{
		pagePicker.select(page);
	}

	/**
	 * Outlines the home button while the first page is shown. Null means no page is shown.
	 */
	public void setShown(Page page)
	{
		List<Page> pages = getPages();
		homeButton.setHighlight(page != null && !pages.isEmpty() && page == pages.get(0) ? colours.getAccent() : null);
	}

	/**
	 * Spins and disables the refresh button while a load the member is waiting on runs.
	 */
	public void setLoading(boolean loading)
	{
		refreshButton.setSpinning(loading ? colours.getAccent() : null);
		refreshButton.setEnabled(!loading);
	}

	/**
	 * Opens the first page, which is Home when the sheet has it.
	 */
	private void openHome()
	{
		List<Page> pages = getPages();
		if (!pages.isEmpty())
		{
			select(pages.get(0));
		}
	}
}

package com.pvknee.ui;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import net.runelite.client.util.LinkBrowser;
import okhttp3.HttpUrl;

/**
 * The only web pages the panel opens: https pages on a few known sites (and their subdomains), so a changed link in
 * the clan sheet cannot send members to any other site.
 */
public final class WebLinks
{
	private static final List<String> SITES = Arrays.asList(
		"discord.gg",
		"discord.com",
		"wiseoldman.net",
		"oldschool.runescape.wiki",
		"runescape.com");

	private WebLinks()
	{
	}

	/**
	 * Whether the panel may open this address: https on one of the known sites.
	 */
	public static boolean isAllowed(String url)
	{
		HttpUrl httpUrl = url == null ? null : HttpUrl.parse(url.trim());
		if (httpUrl == null || !httpUrl.isHttps())
		{
			return false;
		}
		String host = httpUrl.host().toLowerCase(Locale.ENGLISH);
		return SITES.stream().anyMatch(site -> host.equals(site) || host.endsWith("." + site));
	}

	/**
	 * Opens the page in the browser if it is allowed; otherwise does nothing.
	 */
	public static void open(String url)
	{
		if (isAllowed(url))
		{
			LinkBrowser.browse(url.trim());
		}
	}
}

package com.pvknee.wom;

import com.pvknee.DevLog;
import com.pvknee.PvKneeConfig;
import com.pvknee.player.PlayerInfo;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.EnumSet;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.xpupdater.XpUpdaterConfig;
import net.runelite.client.plugins.xpupdater.XpUpdaterPlugin;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * When the member logs out with "Update Wise Old Man on logout" on, asks Wise Old Man to update the name they were
 * logged in as, so the challenge standings are more up to date. Only after progress this session (over 10,000 xp, or
 * a kill or completion count), on a normal world, when XP Updater isn't already sending it, and at most once per 10
 * minutes per name, even across restarts.
 */
@Singleton
public class LogoutUpdate
{
	private static final HttpUrl PLAYERS_URL = HttpUrl.get("https://api.wiseoldman.net/v2/players");
	private static final String USER_AGENT = "PvKnee-RuneLite-Plugin/1.0";
	private static final Duration MIN_GAP = Duration.ofMinutes(10);
	/** The same threshold RuneLite's XP Updater uses. */
	private static final long XP_THRESHOLD = 10_000;
	/** Where the time of the last update for a name is kept in the plugin's config. */
	private static final String SENT_KEY_PREFIX = "womUpdatedAt_";
	/** Worlds whose progress Wise Old Man doesn't track. */
	private static final Set<WorldType> SKIPPED_WORLDS = EnumSet.of(WorldType.SEASONAL, WorldType.DEADMAN,
		WorldType.TOURNAMENT_WORLD, WorldType.BETA_WORLD, WorldType.FRESH_START_WORLD, WorldType.NOSAVE_MODE);
	/**
	 * Kill and completion count messages, as RuneLite's chat commands match them, e.g. "Your Vorkath kill count is:
	 * 123." or "Your completed Chambers of Xeric count is: 45."
	 */
	private static final Pattern COUNT_MESSAGE = Pattern.compile(
		"Your (?:completion count for |subdued |completed )?.+? (?:(?:kill|harvest|lap|completion) )?(?:count )?is: [0-9,]+");

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final PlayerInfo playerInfo;
	private final OkHttpClient okHttpClient;
	private final PvKneeConfig config;
	private final ConfigManager configManager;
	private final PluginManager pluginManager;
	private final XpUpdaterConfig xpUpdaterConfig;
	private final DevLog devLog;

	private boolean loggedIn;
	/** Total xp at the start of this session; -1 until the first tick after login. */
	private long startXp = -1;
	private long latestXp;
	private boolean countSeen;
	private boolean normalWorld;

	@Inject
	LogoutUpdate(Client client, ClientThread clientThread, EventBus eventBus, PlayerInfo playerInfo, OkHttpClient okHttpClient,
		PvKneeConfig config, ConfigManager configManager, PluginManager pluginManager, DevLog devLog)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.playerInfo = playerInfo;
		this.okHttpClient = okHttpClient;
		this.config = config;
		this.configManager = configManager;
		this.pluginManager = pluginManager;
		this.xpUpdaterConfig = configManager.getConfig(XpUpdaterConfig.class);
		this.devLog = devLog;
	}

	public void start()
	{
		eventBus.register(this);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				startSession();
			}
		});
	}

	public void stop()
	{
		eventBus.unregister(this);
		loggedIn = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			if (!loggedIn)
			{
				startSession();
			}
			normalWorld = isNormalWorld();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN && loggedIn)
		{
			loggedIn = false;
			if (config.updateWomOnLogout())
			{
				update(playerInfo.lastName());
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (loggedIn && startXp < 0)
		{
			startXp = client.getOverallExperience();
			latestXp = startXp;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (loggedIn && startXp >= 0)
		{
			latestXp = client.getOverallExperience();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (loggedIn && !countSeen
			&& (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
			&& COUNT_MESSAGE.matcher(Text.removeTags(event.getMessage())).find())
		{
			countSeen = true;
			devLog.log("wom: count message seen");
		}
	}

	private void startSession()
	{
		loggedIn = true;
		startXp = -1;
		latestXp = 0;
		countSeen = false;
		normalWorld = isNormalWorld();
	}

	private boolean isNormalWorld()
	{
		return client.getWorldType().stream().noneMatch(SKIPPED_WORLDS::contains);
	}

	private void update(String name)
	{
		if (name == null)
		{
			return;
		}

		String player = Text.toJagexName(name);
		long gained = startXp < 0 ? 0 : latestXp - startXp;
		if (!countSeen && gained <= XP_THRESHOLD)
		{
			devLog.log("wom: {} made too little progress ({} xp, no counts), skipped", player, gained);
			return;
		}
		if (!normalWorld)
		{
			devLog.log("wom: not a normal world, skipped");
			return;
		}
		if (xpUpdaterSends())
		{
			devLog.log("wom: XP Updater already updates Wise Old Man, skipped");
			return;
		}

		String key = SENT_KEY_PREFIX + Text.standardize(player).replace(' ', '_');
		Instant now = Instant.now();
		Long last = configManager.getConfiguration(PvKneeConfig.GROUP, key, Long.class);
		if (last != null && now.isBefore(Instant.ofEpochMilli(last).plus(MIN_GAP)))
		{
			devLog.log("wom: {} was updated less than 10 minutes ago, skipped", player);
			return;
		}
		configManager.setConfiguration(PvKneeConfig.GROUP, key, now.toEpochMilli());
		send(player);
	}

	/**
	 * Whether RuneLite's XP Updater is on with its Wise Old Man option ticked, so it sends its own update on logout.
	 */
	private boolean xpUpdaterSends()
	{
		Plugin plugin = pluginManager.getPlugins().stream()
			.filter(p -> p instanceof XpUpdaterPlugin)
			.findFirst()
			.orElse(null);
		return plugin != null && pluginManager.isPluginActive(plugin) && xpUpdaterConfig.wiseoldman();
	}

	private void send(String player)
	{
		devLog.log("wom: updating {}", player);
		Request request = new Request.Builder()
			.url(PLAYERS_URL.newBuilder().addPathSegment(player).build())
			.header("User-Agent", USER_AGENT)
			.post(RequestBody.create(null, new byte[0]))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				devLog.log("wom: update for {} failed, {}", player, e.getMessage(), e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				response.close();
				if (response.isSuccessful())
				{
					devLog.log("wom: {} updated", player);
				}
				else
				{
					devLog.log("wom: update for {} failed, response {}", player, response.code());
				}
			}
		});
	}
}

